programs.haiku:
"""Layer-0 MLP down-projection component 4418: "second half of a two-word name".

It responds to the token that completes a multi-word proper name whose first word
is a common name-opener, most strongly after "San" (San| Francisco, San| Diego),
then "Royal" (Royal| Society), and after "Las", "Los", "Santa", "Fort", "New",
"North", "Grand", "Surface" (New| York, Fort| Worth). Weaker responses come from
other capitalised second words of a name ("Times" after "New York"), and a very
weak one from later pieces of a word split across tokens ("Asympt|ote").

The program predicts a size per position from the previous and current token only:
a large value after a name-opener, a moderate one for any other capitalised word that
follows a capitalised word, a very small one for a word-piece, and 0 otherwise.
It explains only a few percent of the variance: the component's variance is spread
over many weak, context-dependent tokens, and token identity alone explains ~13%.
"""

READS = ()

# first words that often open a two-word name, with a typical size of the response
OPENERS = {
    "San": 1.4, "Royal": 0.9, "Las": 0.9, "Los": 0.8, "Santa": 0.8, "Fort": 0.7,
    "New": 0.8, "North": 0.6, "Grand": 0.5, "Surface": 0.6, "Prime": 0.5,
}


def _is_word(text):
    return text.strip().isalpha()


def _is_capitalised(text):
    return text.strip()[:1].isupper()


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0  # a new document starts: nothing to continue
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip()
    if not (_is_word(cur) and _is_word(prev)):
        return None, 0.0
    if prev in OPENERS:
        return None, OPENERS[prev]
    if cur.startswith(" ") and _is_capitalised(cur) and _is_capitalised(prev):
        return None, 0.05
    if not cur.startswith(" "):
        return None, 0.01  # later piece of a word split across tokens
    return None, 0.0

programs.luna:
"""A small capitalization cue, with a larger score after another uppercase word."""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        in_word = False
        word_title = False
        previous_title = False
    else:
        _, in_word, word_title, previous_title = carry

    saw_title = False
    saw_pair = False
    for ch in prefix.token_strings[-1]:
        if ch.isalpha():
            if not in_word:
                word_title = ch.isupper()
                if word_title and previous_title:
                    saw_pair = True
                in_word = True
            if word_title:
                saw_title = True
        elif in_word:
            previous_title = word_title
            in_word = False
            word_title = False

    value = 0.024 if saw_pair else 0.010 if saw_title else 0.0
    return (doc, in_word, word_title, previous_title), value

programs.haiku:
"""Present-tense and future verbs (am, are, is, has, will, want, ...) that come right after a subject."""
READS = ()

BE_AM = {" am", "'m", "’m"}
STRONG = {" are", "'re", "’re", " has", " have", "'ve", "’ve", " will", " shall", "'ll", "’ll"}
PRESENT = {" is", "'s", "’s", " want", " wants", " need", " believe", " believes",
           " hope", " know", " do", " does", " love", " loves", " says"}
ADVERBS = {" also", " currently", " already"}
SUBJECT_WORDS = {"I", "we", "you", "they", "he", "she", "it", "this", "There", "that"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix) < 2:
        return None, 0.0
    prev = prefix.token_strings[-2].strip()
    after_subject = prev in SUBJECT_WORDS or prev[:1].isupper()
    if tok in BE_AM:
        value = 1.0 if after_subject else 0.3
    elif tok in STRONG:
        value = 0.5 if after_subject else 0.35
    elif tok in PRESENT:
        value = 0.5 if after_subject else 0.15
    elif tok in ADVERBS:
        value = 0.3
    else:
        value = 0.0
    return None, float(value)

programs.luna:
"""A low-amplitude cue for common English auxiliaries and copulas."""
READS = ()

AUXILIARIES = {
    "am", "is", "are", "was", "were", "be", "been", "being",
    "has", "will", "would", "need", "'m", "'re", "'ll",
    "’m", "’re", "’ll",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower().strip(" \t\r\n.,!?;:()[]{}\"")
    return None, 0.23 if word in AUXILIARIES else 0.0

programs.sol:
"""A preparation/readiness signal, strongest on forms of 'prepare'.

Smaller positives mark pre-/before, ready, equipping and configuring.
Translations and split-word rules extend the same concepts beyond English.
The signal also reaches the next word in 'preparation of', 'prepared to',
'ready to', and 'set up'. Other tokens receive zero; weak lexical background
and unrelated accidental triggers are deliberately not modeled.
"""
READS = ()

PREPARE_FORMS = {
    'prepare': 6.6, 'prepared': 5.05, 'preparing': 6.15,
    'prepares': 5.45, 'preparation': 4.8, 'preparations': 4.2,
    'prepar': 4.25, 'prep': 3.1, 'prepping': 4.1, 'prepped': 4.4,
}
RELATED = {
    'ready': 1.12, 'readiness': 1.2, 'before': 0.81,
    'beforehand': 0.81, 'equipment': 0.9, 'equipped': 2.05,
    'equip': 1.5, 'setup': 1.4, 'configure': 1.65,
    'configured': 1.27, 'configuring': 1.6, 'configuration': 0.85,
    'configurations': 0.7, 'config': 0.25,
    'adjust': 0.8, 'adjusted': 0.8, 'adjusting': 0.9,
    'planning': 0.65, 'planned': 0.7, 'train': 0.33, 'trained': 0.5,
}
TRANSLATIONS = {
    '准备': 4.15, '準備': 3.2, '预备': 4.0, '准备好': 2.8,
    '准备工作': 3.35, '备': 2.8, '備': 1.9, '준비': 3.6,
    'подготов': 3.2, 'готов': 1.8, 'hazırl': 2.8,
    '配置': 1.2, '配': 1.1, '设备': 0.8, '装备': 2.1,
    '调整': 0.8, '调': 0.8, '調': 0.8, '设置': 0.7, '做': 0.87,
}


def normalize(token):
    return token.strip(' \t\r\n._-/@').lower()


def response(raw, previous):
    w, p = normalize(raw), normalize(previous)
    if p in ('prepare', 'prepared', 'preparing', 'prepares'):
        if w == 'to':
            return 1.5
        if w in ('a', 'an', 'the', 'your'):
            return 1.15
    if (p, w) in (('preparation', 'of'), ('set', 'up'), ('ready', 'to')):
        return {'of': 2.4, 'up': 1.75, 'to': 0.8}[w]
    if p == 'pre' and not raw[:1].isspace():
        full = 'pre' + w
        if full in PREPARE_FORMS:
            return {'prepar': 6.1, 'preparation': 6.2,
                    'prepare': 5.6, 'prep': 2.7}.get(
                        full, PREPARE_FORMS[full] + 0.5)
        if w.startswith('process'):
            return 2.3
        if w == 'heat':
            return 1.9
        if w == 'trained':
            return 2.75
        if raw[:1].isalpha() or raw.startswith('-'):
            return 0.65
    if not raw[:1].isspace():
        if p == 'prepared' and w == 'ness':
            return 3.3
        if p == 'prepar' and w.isalpha():
            return 2.0
        if p == 'подготов' and w.isalpha():
            return 1.9
    if w in PREPARE_FORMS:
        if w == 'prepare' and raw.strip()[:1].isupper():
            return 5.9
        return PREPARE_FORMS[w]
    if w in ('pre', 'pré'):
        if raw.startswith('-'):
            return 2.0
        return 1.5 if raw.strip()[:1].isupper() else 1.0
    if w.startswith(('preprocess', 'preheat')):
        return 2.2
    return RELATED.get(w, TRANSLATIONS.get(w, 0.0))


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    value = response(raw, prev)
    remembered = raw
    if normalize(prev) == 'pre' and not raw[:1].isspace():
        if 'pre' + normalize(raw) in PREPARE_FORMS:
            remembered = 'pre' + normalize(raw)
    return (doc, remembered), float(value)

"""A partial lexical approximation, strongest on possibility constructions.

Tentative modals and habitual qualifiers usually start negative. Subjects such
as 'we' or 'how' raise modal scores; impersonal subjects, capitalized 'This',
and possibility modals in the last 32 tokens lower them. 'Or perhaps' is more
negative than a plain 'perhaps'. Four modal words have document-start values.

A small translation lexicon and weaker grammatical, intensity, capitalization,
and personalization baselines cover additional lexical responses. Unrecognized
tokens return zero: much of the component's weak background is not captured.
Most lexical rules require a lowercase token with a leading space.
"""
READS = ()

# Separate strengths within familiar grammatical/semantic classes.
MODALS = {'may': -0.317, 'might': -0.120, 'could': -0.066,
          'can': -0.021, 'should': 0.013}
QUALIFIERS = {'perhaps': -0.144, 'maybe': -0.015, 'possibly': -0.106,
              'potentially': -0.086, 'likely': -0.044, 'probably': 0.075,
              'usually': -0.185, 'typically': -0.207, 'often': -0.026}
FOREIGN_POSSIBILITY = {'может': -0.470, 'могут': -0.477,
                       'może': -0.376, 'peut': -0.135, 'peuvent': -0.223,
                       'puede': -0.234, 'pueden': -0.329,
                       '可能': -0.224, '可能会': -0.376, '可能是': -0.301,
                       'かもしれません': -0.251}
START_MODAL = {'may': -0.75, 'might': -0.875, 'can': -0.556,
               'could': -0.178}
POSSESSIVES = {'my', 'our', 'his', 'her', 'its', 'their'}
HIGH_DEGREE = {'high', 'higher', 'highest', 'very', 'entire', 'entirely'}
QUANTITY = {'many', 'few', 'several', 'various', 'all', 'each', 'every'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        previous, recent, count = '', (), 0
    else:
        _, previous, recent, count = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    subject = previous.strip().lower()
    value = 0.0
    prose_word = token.startswith(' ') and word == word.lower()
    if prose_word:
        if word in MODALS:
            value = MODALS[word]
            if subject in {'i', 'we', 'he', 'she'}:
                value += 0.078
            if subject == 'we':
                value += 0.04
            if word == 'may' and subject in {'i', 'we'}:
                value += 0.10
            if subject in {'it', 'they', 'this', 'these', 'there'}:
                value -= 0.060
            if subject == 'that':
                value += 0.070
            if subject in {'what', 'how', 'one'}:
                value += 0.115
            if previous in {' This', ' These'} and word in {'could', 'might'}:
                value -= 0.25
            if previous in {' This', ' These', ' It', ' They'}:
                value -= 0.103
            if previous == ' You':
                value -= 0.07
            value -= 0.046 * min(3, count)
            if start and word in START_MODAL:
                value = START_MODAL[word]
        elif word in QUALIFIERS:
            value = QUALIFIERS[word]
            if word in {'perhaps', 'maybe'}:
                if subject == 'or':
                    value -= 0.39 if word == 'perhaps' else 0.263
                value -= 0.014 * min(3, count)
            else:
                value -= 0.056 * min(3, count)
        elif word in FOREIGN_POSSIBILITY:
            value = FOREIGN_POSSIBILITY[word]
        elif word == 'will':
            value = 0.049
        elif word in {'would', 'must', 'shall'}:
            value = 0.021
        elif word == 'capable':
            value = -0.18
        elif word in {'tailored', 'customize', 'customized', 'personalized'}:
            value = 0.27
        elif word in HIGH_DEGREE:
            value = 0.075
        elif word in QUANTITY:
            value = 0.036
        elif word in {'he', 'she', 'it', 'they'}:
            value = -0.028
        elif word in POSSESSIVES:
            value = -0.022
        elif word == 'your':
            value = 0.034
        elif word in {'be', 'are', 'were'}:
            value = -0.020
        elif word in {'of', 'to', 'the', 'and', 'with', 'on', 'at'}:
            value = -0.008
    if token == ' be' and subject in MODALS.keys() | {'would'}:
        value = -0.05
    if word in {'Can', 'Should', 'Must', 'Will', 'Would'}:
        value = 0.080
    if word in {'可能', '可能会', '可能是', 'かもしれません'}:
        value = FOREIGN_POSSIBILITY[word]
    # A bounded history of possibility modals, reset at document boundaries.
    is_modal = int(prose_word and word in {'can', 'could', 'may', 'might'})
    if len(recent) == 32:
        count -= recent[0]
        recent = recent[1:]
    recent += (is_modal,)
    count += is_modal
    return (doc, token, recent, count), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4422 - a negative "Spanish/Portuguese determiner" feature.

The component writes a negative value into the residual stream on the current token
when it is a Romance determiner or clitic: possessive "su"/"sus", plural and demonstrative
determiners ("los", "las", "este", "esta", "esse", "cada"), with the strongest responses;
the singular articles "el", "una", the reflexive "se" and a few others, a medium response;
and the articles "la", "lo", "un", "um", "o", "os", a weak response. Almost every other
token gives about 0. Its response depends only on the current token, not on context.

Values are the mean activation per token, read off 1024 training rows, rounded to three levels.
"""

READS = ()

# Strongest: possessives and plural/demonstrative determiners (mean about -2 to -3).
STRONG = {
    " su", " sus", " los", " las", " este", " esta", " estas", " esse", " esa",
    " cada", " seu", " seus", " nuestros", " nuestra", " Los", " Las", " LOS",
}
# Medium: singular "el", "una", reflexive "se", and a few others (mean about -1).
MEDIUM = {" el", " una", " se", " El", " Se", " EL", " uma", " Su", " tu", " nuestro"}
# Weak: the articles "la", "lo", "un", "um" and "o", "os" (mean about -0.4 to -0.8).
WEAK = {" la", " lo", " un", " um", " o", " os", " mi", " mis", " La", " LA"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in STRONG:
        return carry, -2.0
    if tok in MEDIUM:
        return carry, -1.2
    if tok in WEAK:
        return carry, -0.5
    return carry, 0.0

"""Candidate 4: graded 'head' concept. Strength depends on how head-like the word is."""
READS = ()

HEAD_CORE = {"head", "heads"}                              # the body part, or a leader
HEAD_SENSE = {"headed", "heading", "headings", "ahead"}   # head as a verb, or 'ahead'
HEAD_PART = {"header", "headers", "headline", "headache", "headphones", "overhead"}
HEAD_CHINESE = {"头", "頭"}                                 # head, in Chinese and Japanese
TOP_LEAD_BODY = {"top", "tail", "lead", "leads", "leading", "dead", "neck", "skull", "helm", "helmet"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # the word itself, ignoring case and punctuation such as '_' or '('
    word = "".join(c for c in token.lower() if c.isalpha())
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    prev = "".join(c for c in prev.lower() if c.isalpha())
    if word in HEAD_CORE:
        value = -8.0
    elif word in HEAD_SENSE:
        value = -5.0
    elif token.strip() in HEAD_CHINESE:
        value = -4.8
    elif word in HEAD_PART:
        value = -1.5
    elif word in TOP_LEAD_BODY:
        value = -1.0
    elif token.strip().lower() == "of" and prev in HEAD_CORE:
        value = -4.0
    elif token.strip().lower() == "of" and prev == "ahead":
        value = -2.5
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Recognize head words strongly, with weaker top/front and translated head words."""

READS = ()

HEAD = {"head", "heads"}
HEAD_DERIVATIVES = {"headed", "heading"}
HEAD_TRANSLATIONS = {"头晕", "首", "眼前", "голов", "頭", "首"}
RELATED = {
    "header", "headers", "top", "tops", "upper", "lead", "leads",
    "leading", "leader", "leaders", "front", "fore", "foremost",
    "tail", "tails", "back", "backs", "dead", "deadlock",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,:;!?\\\"'()[]{}<>-_")
    if word in HEAD:
        return None, -8.5
    if word in HEAD_DERIVATIVES:
        return None, -5.8
    if word in HEAD_TRANSLATIONS:
        return None, -1.5
    if word in RELATED:
        if word in {"tail", "tails", "dead", "deadlock"}:
            return None, -1.3
        return None, -0.9
    return None, 0.0

programs.sol:
"""Approximate a d-fragment response at a token boundary.

The main signal is a short token ending in d (also Cyrillic д, Arabic د,
or Thai ด). The following fragment receives a mostly negative response:
repeating d strengthens it, while r can reverse it. Longer fragments and
common complete words weaken the response. A bare d at document start
receives a strong negative value. This is a spelling-based approximation,
not a predictor of all the component's small, token-specific fluctuations.
"""
import unicodedata

READS = ()
D_LETTERS = frozenset('dDдДدด')
COMMON_D_ENDING_WORDS = frozenset('and had would could should did said'.split())
# Letter groups used only to classify the continuing fragment.
TRANSLATE = str.maketrans({
    **dict.fromkeys('дدด', 'd'),
    **dict.fromkeys('рر', 'r'),
    **dict.fromkeys('аا', 'a'),
    **dict.fromkeys('еэє', 'e'),
    **dict.fromkeys('иіыیي', 'i'),
    **dict.fromkeys('о', 'o'),
    **dict.fromkeys('уو', 'u'),
    **dict.fromkeys('ж', 'j'),
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    bare = text.lstrip()
    new_document = carry is None or carry[0] != doc
    value = -0.001
    if new_document:
        if bare and all(c in D_LETTERS for c in bare):
            value = -1.55 if text[:1].isspace() else -2.35
        elif bare.endswith(tuple(D_LETTERS)) and len(bare) <= 2:
            value = -0.6
    elif carry[1].endswith(tuple(D_LETTERS)) and bare:
        previous = carry[1].strip()
        # Fitted attenuation by the previous fragment's length.
        length_scale = (0.0, 1.0, 0.88, 0.65, 0.42, 0.19)
        strength = length_scale[min(len(previous), 5)]
        if previous.lower() in COMMON_D_ENDING_WORDS:
            strength = 0.08
        letters = ''.join(c for c in unicodedata.normalize('NFD', bare.lower())
                          if not unicodedata.combining(c)).translate(TRANSLATE)
        if not letters:
            return (doc, text), float(value)
        first = letters[0]
        if text[0].isspace():
            response = -0.02 - (0.75 if first == 'd' else 0.0)
        else:
            response = 0.04 * min(len(letters), 12)
            if first.isalpha():
                response -= 0.22
            else:
                response -= 0.09 if first.isdigit() else 0.1
            if first == 'd':
                response -= 1.17
            elif first == 'a':
                response -= 0.49
            elif first == 'e':
                response -= 0.34
            elif first == 'j':
                response -= 0.55
            elif first in 'iouy':
                response -= 0.1
            response += 0.23 * letters.count('r')
            response -= 0.61 * letters.count('d')
            if not first.isalpha() and 'd' in letters[:2]:
                response -= 0.57
            length_scale = (1.0, 1.24, 1.0, 0.78, 0.53, 0.44)
            response *= length_scale[min(len(bare), 5)]
        value += strength * response
    return (doc, text), float(value)

"""A token-local data/information vocabulary detector, with negative sign.

'Data' is the main trigger. Metadata, datasets, files, input, content,
information, knowledge and evidence receive weaker negative responses.
Selected translations and tokenized word stems are included. Punctuation and
capitalization alter the strength of 'data'; document-end and tool-result
markers are independent triggers. 'Alternatively' has a small negative
response too. Other tokens are predicted as zero. This is a fixed lexical
approximation: earlier context and unrelated small responses are omitted.
"""

READS = ()

# Translations of data (including the Vietnamese stem of "dữ liệu").
# Fixed strengths were estimated from random training rows.
DATA_TRANSLATIONS = {
    '数据': -3.9,
    '數據': -2.9,
    'データ': -2.6,
    '데이터': -3.2,
    'данные': -1.4,
    'данных': -1.4,
    'datos': -1.25,
    'données': -1.4,
    'daten': -2.1,
    'dados': -0.65,
    'dữ': -2.2,
}
INFORMATION_WORDS = {
    'information', 'informations', 'información', 'informações',
    'информация', 'информации', 'информацию', '情報', '信息',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        return None, -1.71
    if token == '<tool_response>':
        return None, -0.70
    stripped = token.strip()
    word = stripped.strip('_()[]{}.,:;\'"`/$\\-=@').lower()

    if word == 'data':
        value = -4.25
        if stripped.startswith(('(', '[')):
            value = -3.2
        elif stripped.startswith('.'):
            value = -5.0
        elif stripped.startswith(('/', '-')):
            value = -5.35
        elif token == 'Data':
            value = -5.35
        elif stripped.startswith('_'):
            value = -5.2 if stripped[1:2].isupper() else -3.9
        elif token.startswith('\t'):
            value = -4.0
        elif stripped.startswith('\\'):
            value = -4.0
        elif token == 'data':
            value = -4.45
    elif word in {'metadata', 'etadata'}:
        value = -1.6
    elif word in {'datas', 'datab'}:
        value = -2.5
    elif word.endswith('data'):
        value = -3.5
        if word.startswith(('form', 'event', 'cdata')):
            value = -2.6
    elif word.removeprefix('的') in DATA_TRANSLATIONS:
        value = DATA_TRANSLATIONS[word.removeprefix('的')]
    elif '数据' in word:
        value = -2.1
    elif word in {'dataset', 'datasets', 'dataframe'}:
        value = -0.87
    elif word in {'database', 'databases'}:
        value = -0.43
    elif word in {'file', 'files', '文件'}:
        value = -0.83
        if stripped.startswith('('):
            value = -0.60
        elif token == 'file' or stripped.startswith('_'):
            value = -0.70
    elif word in {'input', 'inputs', '输入'}:
        value = -0.72
    elif word in INFORMATION_WORDS:
        value = -0.77
    elif '信息' in word or '情報' in word:
        value = -0.65
    elif word == 'info':
        value = -0.64
    elif word in {'content', '内容'}:
        value = -0.65
    elif word == 'contents':
        value = -0.38
    elif word in {'knowledge', '知識', '知识'}:
        value = -0.63
    elif word == '資料':
        value = -1.5
    elif word == '资料':
        value = -1.1
    elif word == 'alternatively':
        value = -0.45
    elif word == 'evidence':
        value = -0.47
    else:
        value = 0.0
    return None, value

"""Short word-ending fragments, strengthened by an adjacent stem.

This is a spelling-based approximation, not a grammatical parser. Separately
encoded English endings and several non-English inflections respond most.
A longer preceding alphabetic token fragment makes a suffix more convincing;
a vowel-ending fragment generally makes English inflections less convincing.
Only listed spellings receive predictions. An ending can fire inside a
word or by itself; unlisted whole-word tokens and punctuation return zero.
"""

READS = ()

# Ending: baseline, gain per stem letter (up to five), vowel penalty,
# and extra response after a title-cased stem.
ENGLISH = {
    's': (0.21, 0.300, 0.27, 0.13),
    'ed': (0.12, 0.190, 0.35, 0.22),
    'ing': (0.33, 0.124, 0.26, 0.07),
    'er': (-0.11, 0.133, 0.35, 0.05),
    'es': (-0.01, 0.140, 0.28, 0.08),
    'ly': (0.27, 0.121, 0.32, 0.13),
    'ity': (0.12, 0.110, 0.15, 0.05),
    'ation': (0.10, 0.025, 0.13, 0.02),
    'ness': (0.57, 0.016, 0.00, 0.00),
    'e': (0.03, 0.060, 0.20, 0.12),
    'y': (-0.03, 0.078, 0.19, 0.04),
    'al': (-0.20, 0.095, 0.14, 0.02),
}

# Cyrillic case/number endings: baseline and gain per stem letter.
CYRILLIC = {
    'а': (0.18, 0.132), 'ы': (0.21, 0.135),
    'ов': (0.24, 0.089), 'у': (0.25, 0.085),
    'и': (0.07, 0.075), 'е': (0.04, 0.092),
    'ом': (0.09, 0.081), 'ами': (0.12, 0.05),
}

# Longer English ending fragments and inflections in other scripts.
SMALL_ENDINGS = {
    'ers': 0.20, 'ting': 0.55, 'ged': 0.41, 'ging': 0.53,
    'ings': 0.31, 'ful': 0.28,
    'ED': 0.55, 'ING': 0.68, 'LY': 0.62, 'SED': 0.52,
    'ة': 0.58, 'ات': 0.77, 'ς': 0.19,
    '了': 0.73, '们': 1.06, '們': 0.83,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in SMALL_ENDINGS:
        return None, float(SMALL_ENDINGS[token])
    if token not in ENGLISH and token not in CYRILLIC and token != 'S':
        return None, 0.0

    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    # Only the trailing run of letters belongs to the adjacent stem.
    start = len(previous)
    while start and previous[start - 1].isalpha():
        start -= 1
    stem = previous[start:]
    length = min(len(stem), 5)

    if token == 'S':
        if stem.isupper():
            value = 0.36 + 0.285 * length
        else:
            value = -0.06 + 0.064 * length
    elif token in CYRILLIC:
        base, gain = CYRILLIC[token]
        value = base + gain * length
    else:
        base, gain, vowel_penalty, title_bonus = ENGLISH[token]
        value = base + gain * length
        if stem and stem[-1].lower() in 'aeiou':
            value -= vowel_penalty
        if stem.istitle() and len(stem) > 1:
            value += title_bonus
        if token == 's':
            if stem.isupper():
                value += 0.32
            if previous[-1:].isdigit():
                value += 0.29
    return None, float(value)

programs.luna:
"""Predict from especially common word-ending pieces.

It looks at the current token and assigns a small positive activation to a
short list of familiar English and Cyrillic endings, Greek ς, and Chinese 了.
"""

READS = ()

ENGLISH_ENDINGS = {"ing", "ed", "s", "er"}
CYRILLIC_ENDINGS = {"ов", "а", "ы", "у", "и"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token != token.strip() or not token.isalpha():
        return None, 0.0
    if token.lower() in ENGLISH_ENDINGS:
        return None, 0.5
    if token in CYRILLIC_ENDINGS:
        return None, 0.4
    if token == "ς":
        return None, 0.25
    if token == "了":
        return None, 0.45
    return None, 0.0

programs.sol:
"""Detect the written root 'front' and weaker front/order vocabulary.

The response is strongly negative on front, weaker on its compounds, and
smaller on first/before, top/back, forward and translated front/first cues.
Font is a spelling-neighbour false positive. 'Of' and word endings after
front retain some of the cue. Everything else is left at zero.
"""
READS = ()

CUES = (
    (-1.9, {'foremost', 'foreground'}),
    (-1.3, {'ahead', 'forehead'}),
    (-1.1, {'rear'}),
    (-0.94, {'before'}),
    (-0.7, {'forward', 'forwards', 'fore', 'facing', 'faced'}),
    (-0.55, {'straightforward', 'beforehand'}),
    (-0.31, {'backward', 'backwards'}),
    (-3.15, {'frente'}),
    (-2.9, {'앞'}),
    (-2.1, {'当前', '前端'}),
    (-1.8, {'前面', '前方', '眼前', '前沿', 'トップ'}),
    (-1.4, {'正面', '面前', '从前'}),
    (-1.2, {'devant'}),
    (-0.85, {'前', '目前', '第一', '首先'}),
    (-0.7, {'перед', 'før', 'primero', 'première'}),
)


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous, old_value = '', 0.0
    if carry is not None and carry[0] == doc:
        previous, old_value = carry[1:]
    raw = prefix.token_strings[-1]
    clean = raw.strip()
    word = clean.strip('_/,.()[]{}:-').lower()
    capital = any(c.isupper() for c in clean)
    value = 0.0

    if word == 'front':
        value = -7.8
        if clean.startswith(('_', '.')):
            value = -6.6
    elif word == 'fronts':
        value = -6.25
    elif 'confront' in word:
        value = -1.7 if 'ation' in word else -2.4
    elif 'front' in word:
        value = -1.7 if word in {'waterfront', 'storefront'} else -3.6
    elif word in {'fron', 'ront'}:
        value = -6.6 if previous == 'f' else -3.0
    elif word in {'first', 'firstly', 'firsthand'}:
        value = -1.02 if capital else -0.84
    elif word == 'top':
        value = -0.74 if capital or not raw[:1].isspace() else -1.05
    elif word == 'back':
        value = -0.8 if capital else -0.6
    elif word in {'font', 'fonts'}:
        value = -0.8 if capital else -1.0
    else:
        for strength, words in CUES:
            if word in words:
                value = strength
                break

    if word == 'of':
        if 'front' in previous:
            value = 0.47 * old_value
        elif previous in {'top', 'back', 'ahead'}:
            value = -0.34
    elif (value == 0.0 and previous in {'front', 'confront', 'ront'}
          and not raw[:1].isspace()):
        if word in {'s', 'ed', 'ing'}:
            value = 0.45 * old_value
        elif word in {'al', 'iers'}:
            value = 0.25 * old_value
        elif word.isalpha() or raw == '-end':
            value = 0.16 * old_value
    return (doc, word, value), float(value)

programs.haiku:
"""Fires negatively on words of position and precedence. 'front' is the strongest
trigger (also 'Front', 'FRONT' and words containing it), then 'first', 'before',
'top', 'ahead', 'forward', 'back' and their translations, plus 'of' right after
'front' (as in 'in front of')."""

READS = ()

PRECEDENCE = {
    "first": -1.0, "firstly": -1.2, "before": -1.0, "top": -1.0,
    "ahead": -1.2, "forward": -0.8, "back": -0.6, "rear": -1.1,
    "fore": -0.7, "foremost": -1.5, "前": -0.9, "目前": -0.9, "第一": -0.8,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if "front" in word:
        value = -8.0 if word == "front" else -3.5
    elif word == "of" and prev == "front":
        value = -3.5
    else:
        value = PRECEDENCE.get(word, 0.0)
    return None, value

programs.luna:
"""A sparse cue for words about being first, forward, or at the top/front."""

