programs.sol:
"""A negative lexical signal for dictionary spellings, ict, and prediction words.

List/tuple names and conflict words also fire more weakly. The tests operate
on readable token spellings, not token IDs. Identifier punctuation changes
some strengths. Split prediction endings and 'dictionary of' phrases retain
a signal on the next token. All other tokens receive zero; this leaves the
component's numerous small, less systematic responses unexplained.
"""
READS = ()
PUNCTUATION = '_.,:;=()[]{}<>-/\\`"\''
COLLECTIONS = {'list', 'lists', 'tuple', 'tuples', 'arraylist', 'hashmap'}
PREDICTION_ENDINGS = {'ive', 'ion', 'ions', 'or', 'ors', 'ed', 'ing', 'able'}


def lexical(token):
    raw = token.strip()
    spelling = raw.strip(PUNCTUATION)
    word = spelling.lower()
    value = 0.0
    if word == 'dict':
        if raw.startswith('_'):
            value = -3.9
        elif raw.startswith('.'):
            value = -4.1
        elif raw != spelling:
            value = -5.1
        elif spelling == 'dict':
            value = -6.1
        else:
            value = -4.8 if token[:1].isspace() else -5.55
    elif word in {'dictionary', 'dictionaries', 'ictionary', 'ictionaries'}:
        value = -4.5 if word.endswith('ies') else -3.8
    elif word in {'dicts', 'defaultdict'}:
        value = -2.5 if raw.startswith('_') or word == 'defaultdict' else -4.4
    elif word == 'ict':
        value = -2.1 if token[:1].isspace() else -4.6
    elif word in {'iction', 'ictions', 'icted', 'icts', 'ikt'}:
        value = -1.7
    elif word in {'dic', 'vict', 'rict'}:
        value = -1.3
    elif word == 'pict':
        value = -2.4
    elif word.startswith(('predict', 'unpredict')) or word == 'redict':
        if word.endswith(('ion', 'ions', 'or', 'ors', 'able')):
            value = -1.7
        elif word.endswith('ed'):
            value = -1.85
        elif word.endswith(('ing', 'ive')):
            value = -2.2
        else:
            value = -3.1 if spelling == 'Predict' else -2.65
    elif word.startswith(('dictat', 'addict')):
        value = -2.7 if word.startswith('dictat') and word != 'dictatorship' else -1.4
    elif word in COLLECTIONS or word in {'列表', '元组'}:
        value = -0.82
    elif word.startswith('contradict'):
        value = -1.05
    elif word.startswith('conflict') or word in {'lict', 'licts', '矛盾'}:
        value = -0.75
    elif word == '预测':
        value = -1.65
    elif word == '典':
        value = -1.2
    return word, value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word, value = lexical(token)
    previous = carry[1] if carry is not None and carry[0] == document else ''
    if token == ' of':
        if previous in {'dictionary', 'dictionaries', 'dict'}:
            value = -2.0 if previous != 'dict' else -2.8
        elif previous.startswith('predict'):
            value = -1.1
    elif token in PREDICTION_ENDINGS and previous.endswith(('predict', 'redict')):
        value = -3.1 if token == 'ive' else -1.8
    elif word == 'dict' and previous == 'ver':
        value = -3.0  # The second piece of "verdict", not a dictionary name.
    elif word == 'ict' and previous in {'restr', 'ev'}:
        value = -1.6 if previous == 'restr' else -3.5
    return (document, word), float(value)

programs.luna:
"""A lexical sketch of this component's strongest recurring word cues.

It recognizes prediction, dictionary/list, and conflict words, plus a few
small positive cues found in power-of phrases, sibling words, and equality
assertion code.  It deliberately leaves the rest near zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    bare = token.strip().strip(".,:;()[]{}<>\"'`")

    previous = ""
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].casefold().strip()
        previous = previous.strip(".,:;()[]{}<>\"'`")

    if "predict" in token:
        value = -2.1
    elif any(root in token for root in ("contradict", "indict", "edict")):
        value = -1.0
    elif "dict" in token:
        value = -5.5 if bare == "dict" else -3.5
    elif "list" in token:
        value = -0.65
    elif "conflict" in token:
        value = -0.7
    elif "award" in token:
        value = -0.5
    elif bare == "of" and previous in ("power", "powers"):
        value = 0.75
    elif "sibling" in token:
        value = 0.4
    elif "appellant" in token:
        value = 0.35
    elif "_eq" in token:
        value = 0.4
    else:
        value = 0.0

    return None, float(value)

programs.haiku:
"""Causation and purpose words drive this component, plus the document-end token.

The component writes a large value into the residual stream on words that name a
cause ("cause", "causes", "caused", "causing", 导致/造成), a smaller one on
reason/purpose words ("purpose", "reason", "why", "because", "due"), a small one on
connectives such as "through", "then", "trigger", "expected", a middling one on
words for being affected by something ("suffer", 被, 受), and a faint one on
modals, "use", and in-order-to (为了). It also fires on the <|endoftext|> token
that ends a document. Everything else predicts 0.
"""
READS = ()

# Cause verbs and nouns: the strongest response.
CAUSE_EN = {"cause", "causes", "caused", "causing"}
CAUSE_PARTS = {"caus", "ause", "causal"}   # word fragments and adjective
CAUSE_OTHER = {"导致", "造成", "引起", "引发", "致", "причин", "прич", "выз"}

# Purpose and reason words.
PURPOSE = {"purpose", "purposes", "为了"}
REASON = {"reason", "reasons", "why", "because", "due", "原因", "因为", "因", "是因为"}

# Connectives that often introduce a cause, result, or means.
LINK = {"through", "then", "during", "via", "expect", "expected", "trigger",
        "triggered", "triggering", "prevent", "therefore", "thereby", "resulting",
        "induced", "lead", "damage"}

# Being affected by a cause: suffer, undergo, passive marker.
AFFECTED = {"suffer", "suffered", "suffers", "subjected", "被", "受", "遭"}

# Modals and "use": faint.
WEAK = {"would", "will", "use", "used", "uses", "会"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if s == "<|endoftext|>":
        v = 1.7
    elif w in CAUSE_EN:
        v = 6.0
    elif w in CAUSE_PARTS:
        v = 3.5
    elif w in CAUSE_OTHER:
        v = 2.5
    elif w in PURPOSE:
        v = 1.9
    elif w in REASON:
        v = 0.9
    elif w in LINK:
        v = 0.6
    elif w in AFFECTED:
        v = 0.9
    elif w in WEAK:
        v = 0.3
    else:
        v = 0.0
    return None, v

