"""A sparse lexical guess for a few repeatable negative responses.
“Middle” is strongest; “high”, “school”, and several “mid” words are weaker.
After “middle”, “of” and “class” also get a smaller response. Other tokens
are treated as inactive.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    same_document = (
        len(prefix.token_strings) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    if same_document:
        previous = prefix.token_strings[-2].strip().lower()
    if word == "middle":
        return None, -8.0
    if word == "high":
        return None, -1.1
    if word == "school":
        return None, -1.7
    if word in {"midst", "midfielder", "midpoint", "mid", "midwest"}:
        values = {
            "midst": -2.9,
            "midfielder": -0.8,
            "midpoint": -0.9,
            "mid": -1.2,
            "midwest": -0.9,
        }
        return None, values[word]
    if previous.endswith("middle") and word == "of":
        return None, -3.3
    if previous.endswith("middle") and word == "class":
        return None, -0.8
    return None, 0.0

programs.sol:
"""A sparse, signed response to split compounds and organizational labels.

Main+stream and Content+-Type are positive examples; sub+division,
home+page and blog+post are negative ones. Token boundaries matter:
a whole token spelling 'subsection' is not treated as section after sub.
Markup, selected common words and punctuation receive smaller empirical
offsets. Most weak token-specific variation is left unmodeled. State is
only the previous token and its document label, reset at document boundaries.
"""
READS = ()

SUBDIVISIONS = set('section sections division divisions category categories'.split())
SUBSTRUCTURES = set('type types class classes group groups unit units committee '
                    'folder folders directory directories header head path graph tree '
                    'view model models window'.split())
ORGANIZATIONAL_LABELS = set(
    'menu content body page pages window subject campus hall stage '
    'category categories section sections sidebar post posts blog '
    'header tab tabs news search tag tags archive archives '
    'article articles notice links directory departments'.split()
)
MAIN_SUBJECTS = set('character memory engine idea method focus'.split())
RELATED_ITEMS = set('posts post links documents videos articles categories topics'.split())
CONTENT_PROPERTIES = set('-type -length -disposition -based values delivery management '
                         'creation type length'.split())
LEXICAL_BASELINE = {
    'help': 0.08, 'helps': 0.08, 'helping': 0.08,
    'need': 0.05, 'needs': 0.05,
    'does': 0.044, 'did': 0.05,
    'should': -0.041, 'shall': -0.033, 'might': -0.038,
    'enough': 0.093, 'almost': 0.09,
    'within': -0.045, 'beyond': -0.144,
    'toward': -0.070, 'towards': -0.094,
}


def response(token, previous, start):
    word = token.strip().lower()
    before = previous.strip().lower()
    if before == 'sub':
        if word.lstrip('-_') in SUBDIVISIONS:
            return -0.35 if token.startswith(('-', '_', ' ')) else -0.57
        if word.lstrip('-_') in SUBSTRUCTURES:
            return -0.17
        if word == 'vers':  # sub-vers-ive
            return 0.52
        if word == 'string':  # substring
            return 0.34
        if token.isalpha():
            return 0.055
    if before == 'main':
        if word.lstrip('_') == 'menu':
            return -0.30 if token.startswith('_') else -0.60
        if word in {'page', 'pages'}:
            return -0.40
        if word in {'body', 'content', '-page'}:
            return -0.22
        if word.lstrip('-_') in ORGANIZATIONAL_LABELS:
            return -0.125
        if word == 'stream':
            return 0.53 if token == 'stream' else 0.10
        if word == 'z':  # Mainz
            return 0.50
        if word == 'e':  # Maine, Jermaine
            return 0.21
        if word == 'line':
            return 0.50 if token.strip().istitle() else 0.28
        if word in {'point', 'attention'}:
            return 0.40
        if word in MAIN_SUBJECTS:
            return 0.24
        if token.isalpha():
            return 0.072
    if before == 'blog' and word in {'post', 'posts', 'feed', 'article', 'sites'}:
        return -0.32
    if before in {'home', 'product', 'sidebar'} and word in {'page', 'pages'}:
        return -0.36
    if before == 'home' and word == 'omorphic':
        return 0.45
    if before == 'content':
        if token == '-Type' and previous.strip() == 'Content':
            return 0.45
        if word in CONTENT_PROPERTIES:
            return 0.16
    if before == 'related' and word in RELATED_ITEMS:
        return -0.35 if word in {'post', 'posts', 'links', 'categories'} else -0.10
    if word == 'sidebar':
        return -0.37 if before in {'right', 'left', 'toolbar'} else -0.17
    if word.lstrip('_') == 'menu' and token.strip() != 'menu':
        return -0.13
    if start and word in ORGANIZATIONAL_LABELS and not token.strip().islower():
        return -0.30
    if token.lower() == '_modules':
        return -0.088
    if token in {'<think>', '</think>'}:
        return -0.094
    if token == '<tool_response>':
        return -0.048
    if token == '<|im_end|>':
        return -0.030
    if token.startswith(' ') and token[1:] in LEXICAL_BASELINE:
        return LEXICAL_BASELINE[token[1:]]
    if token == '"':
        return -0.028
    if token == '\":':
        return 0.024
