"""An orthographic detector strongest on Czech long vowels and suffixes.

A decaying trace of distinctive Czech letters/words sets the language context.
Short acute-vowel fragments then give large positive predictions; unaccented
vowel/glide fragments give negative ones. Several Slavic endings and letters
have smaller responses. All constants approximate training-set averages.
"""
READS = ()
CZECH_WORDS = {
    'czech', 'czechoslovak', 'kter', 'js', 'jsem', 'jsme', 'jste', 'jsou',
    'bude', 'budu', 'bylo', 'byli', 'tedy', 'také', 'ještě', 'aby', 'abyste',
}
# Ordinary / Czech / other Slavic spelling contexts, respectively.
ACUTE = {
    'á': (.45, 3.5, 1.5),
    'é': (0., 2.9, 1.2),
    'í': (.4, 3.7, 1.5),
    'ý': (1.4, 2.9, 1.2),
}
LETTERS = {'ě': 1.28, 'ř': 1.6, 'ů': .87, 'ň': .65,
           'č': .35, 'ž': .25, 'š': .15, 'ú': .65}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0., 0.)
    _, czech, slavic = carry
    token = prefix.token_strings[-1]
    w = token.strip().lower()
    czech_level = min(1., 20*czech)
    slavic_level = min(1., 20*slavic) * (1-czech_level)
    # Unmatched spellings have no predicted contribution.
    value = 0.
    if any(c in w for c in ACUTE):
        accent = next(c for c in 'íáýé' if c in w)
        b, cz, sl = ACUTE[accent]
        strength = b + czech_level*(cz-b) + slavic_level*(sl-b)
        if w == accent and not token[:1].isspace():
            value = strength
        elif w == 'ní':
            value = 3.4 + czech_level
        elif w in {'ání', 'ení'}:
            value = 2.1
        elif len(w) <= 3:
            scale = .73 if w.endswith(accent) else .43
            value = strength * scale
        elif len(w) <= 5 and not w.endswith(accent):
            value = strength * .25
    elif any(c in w for c in LETTERS):
        c = next(c for c in LETTERS if c in w)
        scale = 1. if c in 'ěřůň' else .3+.7*czech_level+.3*slavic_level
        value = LETTERS[c] * scale
    elif w == 'ou':
        value = .17 + 2.1*czech_level + .8*slavic_level
    elif w == 'ov':
        value = 1.1*czech_level + .4*slavic_level
    elif w in {'a','i','u','y','j','l','li','ci','ni','em','el','al','ry','ty'}:
        value = -.6*czech_level - .1*slavic_level
    elif w in {'ho','ch','m','ed'} and not token[:1].isspace():
        value = .6*czech_level + .2*slavic_level
    elif any(c in w for c in 'ієїґ'):
        value = .3
    elif w == 'ня':
        value = .7
    elif w in {'сь','ий','ый','ого','ок','ув','их'}:
        value = .17
    strong = any(c in w for c in 'ěřů') or w in CZECH_WORDS
    weak = any(c in w for c in 'ýňďťčžš')
    return (doc, .96*czech+strong, .96*slavic+weak), float(value)

