FORMAL_METHOD = {"method", "methods", "procedure", "procedures"}
METHOD_ZH = {"方法", "手法", "方式"}
NEG_WORDS = {"without", "within", "outside", "inside", "including", "because"}
DEGREE_POS = {"least", "few", "enough", "never", "ever", "both", "already", "just"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if s.strip() in FLY_FULL:
        v = 0.4
    elif w in FORMAL_METHOD or s.strip() in METHOD_ZH:
        v = -0.09
    elif w in NEG_WORDS:
        v = -0.06
    elif w in DEGREE_POS:
        v = 0.08
    else:
        v = 0.0
    return carry, float(v)

