        if s in {'集中', '空中', '命中', '中に'}:
            return 4.5
        if s in {'中间', '中途', '途中', '中学'}:
            return 3.5
        if s.endswith(('中', '中的')) or s == '中の':
            return 5.8
        return 2.8
    if s == 'なか':  # Japanese 'middle/inside'
        return 3.8
    if w == 'middle':
        return 2.2 if title else 2.9
    if w in {'central', 'centrally'}:
        return 2.0 if title else 2.2
    if w in {'medium', 'mediums'}:
        return 1.4 if title or not token.startswith(' ') else 1.95
    if w in {'center', 'centre'}:
        return 1.17
    if w in {'centers', 'centres', 'centered', 'centred', 'centralized'}:
        return 0.8
    if w in {'mid', 'midd', 'iddle', 'midpoint', 'midway', 'midfielder',
             'midfield', 'middleware', 'iddleware'}:
