    if w in {'neutral', 'intermediate', 'intermedi', 'intermediary'}:
        return 1.1
    if w == 'among':
        return 1.7 if title else 1.4
    if w in {'amongst', 'china'}:
        return 1.0
    if w == 'chinese':
        return 1.6
    if w in {'after', 'fter'}:
        return 0.8
    if w == 'between':
        return 0.7 if title else 0.4
    if w in {'wherein', 'therein', 'moderate', 'moderately', 'midnight'}:
        return 0.6
    if w in {'amid', 'amidst'}:
        return 0.5
    if s in {'上', '上的', '下', '下的', '内', '內', '里', '裡', '里的', '等',
             'など', '期间'}:
        return 1.0
    if s in {'里面', '裡面', '之间', '之間', '之间的'}:
        return 1.7
    if s in {'前', '之前', '当', '當', '时', '后', '後', '之后', '間', '间'}:
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = lexical(token)
    singular = previous.removesuffix('s')
    if word == 'between':
        if singular in RELATIONS:
            value = -0.15
        elif singular in COMPARISONS:
            value = 0.05
        elif previous == 'in':
            value = 0.95
        elif previous in {'is', 'are', 'be', 'was', 'were', 'located'}:
            value = 0.68
    elif word == 'among' and singular in RELATIONS | COMPARISONS:
        value = 0.9
    elif word == 'of' and previous in {'center', 'centre', 'centers',
                                      'centres', 'medium'}:
        value = 0.6
    return (doc, word), float(value)

