"""A sparse lexical cue for middle, central, and in-between meanings."""

READS = ()

# English words associated with a middle or position within a group.
MIDDLE_WORDS = {
    "middle": 2.8,
    "midst": 2.1,
    "midpoint": 1.4,
    "center": 1.2,
    "centre": 1.2,
    "central": 2.1,
    "medium": 2.0,
    "among": 1.4,
    "between": 0.46,
    "after": 0.88,
    "wherein": 0.7,
    "mid": 1.54,
}

# Chinese/Japanese words for being in, among, before, or during something.
ASIAN_WORDS = {
    "前": 0.9,
    "期间": 1.1,
    "世界上": 1.2,
    "网上": 1.2,
    "里": 0.8,
    "当": 0.8,
    "等": 0.9,
    "では": 0.7,
    "により": 0.5,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.lstrip("([{\"'`:#")

    # 中 means middle/inside; it also occurs in Chinese words about China,
    # position, and being within something.
    if word == "中":
        return None, 9.3
    if word.endswith(("中的", "中")) or word.startswith("中有"):
        return None, 5.5
    if "中" in word:
        return None, 2.3

    # These Chinese endings commonly say that something is on, in, or within.
    if word.endswith(("上", "里", "裏", "内", "內")):
        return None, 1.2

    if word.startswith(("china", "chinese")):
        return None, 1.5
    if word.startswith("zh"):
        return None, 1.2
    for term, value in MIDDLE_WORDS.items():
        if word.startswith(term):
            return None, float(value)
    for term, value in ASIAN_WORDS.items():
        if word.startswith(term):
            return None, float(value)
    if word.startswith(("moderately", "medio")):
        return None, 0.5
    return None, 0.0

programs.sol:
"""A lexical 'we' signal, with weaker responses to inclusive invitations.

We/WE is stronger than we; token boundaries and document beginnings matter.
Clause-opening words weaken lowercase we, and a comma strengthens it.
Recent repetition weakens the response. Several translations of we, short
we-like spelling fragments, and 'let me/us/\'s' also respond negatively.
Unrecognized tokens predict zero, omitting weaker token-specific effects.
"""
import math

READS = ()

# First-person plural subjects: German, Russian, Chinese, French, Dutch.
WE_TRANSLATIONS = {
    'wir': -1.6, 'мы': -1.33, '我们': -1.1, '我們': -1.05,
    'nous': -0.44, '咱们': -0.65, 'wij': -0.33,
}
CLAUSE_LINKS = {'that', 'which', 'what', 'when', 'as', 'how'}
AUXILIARIES = {
    'do', 'did', 'does', 'are', 'were', 'can', 'could', 'should',
    'would', 'will', 'shall', 'have', 'had', 'must',
}
PERMISSION = {'let', 'allow', 'allows', 'allowed', 'allowing'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    pos = 0 if start else carry[1] + 1
    previous = '' if start else carry[2]
    recent = () if start else tuple(t for t in carry[3] if pos - t <= 20)
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev_word = previous.strip().lower()
    spaced = token.startswith(' ')
    value = 0.0

    # Quotations and paths sometimes attach punctuation to the spelling we.
    bare = word.lstrip('"“\'‘/.-_(')
    if bare.lower() == 'we':
        if bare != word:
            value = -4.7
        elif word == 'we':
            value = -3.2 if spaced else -4.0
            if spaced:
                if prev_word == 'if':
                    value += 1.1
                elif prev_word in CLAUSE_LINKS:
                    value += 0.4
                elif prev_word in AUXILIARIES:
                    value += 0.7
                elif previous.rstrip().endswith(','):
                    value -= 0.4
                elif prev_word in {'so', 'since', 'now'}:
                    value -= 0.3
        else:
            value = -3.96 if spaced else -4.32
        value += 0.04 - 0.57 * math.exp(-pos / 60.0)
        value += 0.28 * min(len(recent), 2)
        recent += (pos,)
        if start:
            value = (-4.24 if word == 'we' else -6.17) if spaced else -7.45
    elif len(lower) == 3 and lower.isalpha() and lower.endswith('we'):
        value = -1.6
    elif len(lower) == 3 and lower.isalpha() and lower.startswith('we'):
        value = -0.45
    elif lower in WE_TRANSLATIONS and (lower != 'мы' or spaced):
        value = WE_TRANSLATIONS[lower]
        if word[0].isupper() and lower in {'wir', 'мы'}:
            value -= 0.2
    elif word == 'me' and spaced:
        value = -0.94 if prev_word == 'let' else -0.12
        if prev_word in PERMISSION and prev_word != 'let':
            value = -0.52
    elif word == 'us' and spaced:
        value = -1.42 if prev_word in PERMISSION else -0.85
    elif word in ("'s", '’s') and prev_word == 'let':
        value = -1.81 if word == "'s" else -1.63
    return (doc, pos, token, recent), float(value)

