"""layers.0.mlp.down_proj:4435: a first-person-plural detector with a negative sign.

The component goes strongly negative on the subject pronoun "we" in any casing, and
moderately negative on the same idea in other languages (German "wir", French "nous",
Russian "мы", Chinese "我们" and so on). It is weaker on the object "us" and on the
"us" hidden in "let's" and "let me" constructions. Everywhere else it sits near zero.

Predicted activation, per token (the token is matched on its text, the previous token
for the "let" cases):
  "We" (capital, no space)            -> -4.4
  " We" (capital, after a space)      -> -3.9
  " we" (lowercase, after a space)    -> -3.2
  "we" (lowercase, no space)          -> -4.0
  first-person-plural pronoun, other language -> -1.5
  "'s" right after "let"              -> -1.8   (let's = let us)
  " us"                               -> -0.9
  " me" right after "let"             -> -1.0   (let me)
  " me" elsewhere                     -> -0.5
  anything else                       -> 0.0
"""

READS = ()

# First-person plural pronouns in other languages (lowercased, spaces stripped).
OTHER_WE = {"wir", "zwe", "nous", "nosotros", "nosotras", "noi", "wij", "мы", "我们"}
LET_S = {"'s", "’s"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if tok == "We":
        value = -4.4
    elif tok == " We":
        value = -3.9
    elif tok == " we":
        value = -3.2
    elif word == "we":
        value = -4.0
    elif word in OTHER_WE:
        value = -1.5
    elif tok in LET_S and prev == "let":
        value = -1.8
    elif tok == " us":
        value = -0.9
    elif tok == " me":
        value = -1.0 if prev == "let" else -0.5
    else:
        value = 0.0
    return carry, float(value)

