"""A local grammatical feature centered on English do-support.

It responds most strongly to not/n't directly after do, does, or did.
Their negative contraction stems respond more weakly, as do I/we/you/they;
these pronouns are amplified after do and after conditional/time words.
Several non-English negative particles also respond. Values depend on the token's
spelling, including capitalization and some split contractions. Other
tokens are zero. State contains just two preceding tokens, reset for each document.
"""
READS = ()
DO = {'do', 'does', 'did'}
WH = {'what', 'how', 'why', 'where', 'when'}
CONDITIONAL = {'if', 'whether', 'unless'}
TEMPORAL = {'when', 'while', 'once', 'before', 'after', 'since'}
MODAL = {'can', 'could', 'will', 'would', 'shall', 'should', 'may', 'might', 'must'}
# Pronoun response: ordinary clause, conditional clause, question with do.
SUBJECT = {
    'i': (0.4, 1.0, 1.95), 'we': (0.87, 1.42, 2.95),
    'you': (0.47, 1.38, 3.3), 'they': (0.6, 0.91, 2.15),
}
NEGATIVE_DO = {'don': 1.36, 'doesn': 1.85, 'didn': 1.53}
NOT_DO = {'do': 6.55, 'does': 6.5, 'did': 6.15}
NT_DO = {'don': 6.25, 'doesn': 6.0, 'didn': 5.15}
NEGATIVE_PARTICLES = {
    '不': 2.83, '并不': 3.35, '也不': 1.38, '都不': 1.25,
    '不要': 1.0, 'не': 1.08, 'não': 0.8, 'nicht': 0.36,
    'không': 1.85, 'tidak': 2.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, older = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = old.strip().lower()
    prev2 = older.strip().lower()
    value = 0.0
    if word == 'not':
        value = NOT_DO.get(prev, -0.2)
        if prev in DO and older.strip() == 'I':
            value += 0.2 if prev == 'did' else 0.45
        elif prev == 'will':
            value = 0.83
        elif prev in {'would', 'shall'}:
            value = 0.5
        elif prev in {'should', 'may', 'might', 'am', "'m", '’m'}:
            value = 0.27
        if token.strip() == 'NOT' and prev in DO:
            value *= 0.75
    elif word in {"'t", '’t'}:
        value = NT_DO.get(prev, -0.2)
        if prev in NT_DO and older.strip() == 'I':
            value += 0.6 if prev == 'don' else 0.4
        elif prev == 'won':
            value = 0.72
        elif prev == 'wouldn':
            value = 0.33
        if token.strip() == "'T" and prev in NT_DO:
            value *= 0.66
    elif (word == 't' and prev in {"'", '’', "\\'"}
          and prev2 in NEGATIVE_DO):
        value = 4.4  # An apostrophe, possibly escaped, is a separate token.
    elif word == 'nt' and prev in DO:
        value = 3.2  # The apostrophe was omitted.
    elif word == 't' and prev in NEGATIVE_DO:
        value = 2.35  # An apostrophe was replaced by a space.
    elif word in NEGATIVE_DO:
        value = NEGATIVE_DO[word] + (0.25 if old.strip() == 'I' else 0.0)
        if token == word:
            value -= 0.4  # Unspaced lowercase stems are often word fragments.
    elif word in {'dont', 'doesnt', 'didnt'}:
        value = 3.0 if word == 'dont' else 4.6
    elif word in DO:
        value = {'do': -0.55, 'does': 0.95, 'did': 0.08}[word]
        if prev in WH:
            value += 0.95
        elif prev in MODAL or prev in {'to', "'t", '’t', 'not'}:
            value -= 0.6
        if token.strip()[0].isupper():
            value += 0.4
    elif word in SUBJECT and (word != 'i' or token.strip() == 'I'):
        ordinary, conditional, question = SUBJECT[word]
        value = ordinary
        if prev in DO:
            value = question
        elif prev in CONDITIONAL:
            value = conditional
        if prev in TEMPORAL:
            value += {'i': 0.25, 'we': 0.25, 'you': 0.4, 'they': 0.12}[word]
        elif prev in {'what', 'how', 'whatever'}:
            value += 0.26
        elif word == 'you' and prev in {'thank', 'give', 'giving', 'inform'}:
            value = 0.0
    elif word == 'please':
        value = 0.82
    elif word in NEGATIVE_PARTICLES:
        value = NEGATIVE_PARTICLES[word]
        if word == 'не' and not token.startswith(' '):
            value = 0.12
        elif word == '不' and token.startswith(' '):
            value = 1.9
    return (doc, token, old), float(value)

