"""Draft 3: do-support negation and questions.

Fires on the negation word of a do-support negation ("do not", "does n't", "did not",
"don't"), which is where the component is strongest. Weaker on the auxiliary itself, on
other negation words (Chinese 不, Russian не, Vietnamese không), and on subject pronouns
(you, we, I, they), strongest on "you" right after do/does/did in a question. The main verb
"do" is slightly negative.
"""
READS = ()

DO_AUX = {"do", "does", "did", "don", "doesn", "didn", "dont", "Do", "Does", "Did", "Don", "Doesn", "Didn", "Dont"}
DO_AUX_PIECES = {"don", "doesn", "didn", "dont", "Don", "Doesn", "Didn"}
NEG = {"not", "NOT", "Not", "n't", "’t", "'t", "'T", "nt", "t"}
NEG_OTHER = {"不", "并不", "不会", "không", "ไม่", "не"}
PRONOUN = {"you", "You", "we", "We", "I", "they", "They"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if cur in NEG and prev in DO_AUX:
        return None, 6.5  # negator of do-support: "do not", "don't", "did not"
    if cur in DO_AUX_PIECES:
        return None, 1.5  # the "don"/"doesn" piece of a contracted negation
    if cur in NEG_OTHER:
        return None, 2.0  # negation in other languages
    if prev in DO_AUX and cur in PRONOUN:
        return None, 2.5  # "do you", "do I": a do-support question
    if prev in DO_AUX and cur not in NEG:
        return None, 0.5
    if cur in PRONOUN:
        return None, 0.7
    if cur == "do":
        return None, -0.7
    return None, 0.0

