def person_character(word):
    if word in {'人', '的人', 'の人'}:
        return -5.4
    if word in {'有人', '让人', '讓人', '给人', '給人', '被人',
                '没有人', '沒有人', '每个人', '每個人', '用人', '做人', '为人', '為人'}:
        return -3.8
    if word in {'个人', '個人', '他人', '别人', '別人', '人员',
