    elif word in HUMAN_ROOTS:
        value = -3.8 if token == ' human' else -3.4
    elif word in PERSON_WORDS:
        value = -2.8 if token != 'person' else -1.8
    elif word in PEOPLE_WORDS:
        value = -2.2
    elif token == ' лю':
        value = -2.4
    elif word in {'erson', 'uman'}:
