programs.haiku:
"""Person-word detector (negative). This MLP unit writes a strong negative value into
the residual stream on words for human beings: the Chinese 人 ("person") and its
compounds (人类, 人们, 的人, ...), "human(s)", "person(s)", "people", and the same
words in other languages (사람, người, persone, Menschen, человек, الناس, kişi, człowiek).
Compounds that name a role or type of person (病人 patient, 工人 worker, 男人 man) are
weaker. Generic group words ("everyone", "someone", "others", "individuals") and
"user" (and identifiers containing it) are weaker still. "personal", "personnel" and
"personality" are not about people, so they are weak too. Everything else, including
gendered words (woman, men, women, Mann, homme), is 0.
The value depends only on the token itself, not on context: a lookup of word classes.
"""

READS = ()

HUMAN_WORDS = {"사람", "người", "persone", "persona", "pessoa", "menschen", "человек",
               "людей", "люди", "الناس", "شخص", "kişi", "insan", "człowiek", "אדם", "אנשים",
               "คน", "인간", "사람들"}
ROLE_NOUNS = {"男人", "女人", "军人", "老人", "工人", "病人", "主人", "家人", "负责人",
              "创始人", "机器人", "恋人", "情人", "本人", "法人", "人民币", "华人", "敌人",
              "爱人", "责任人", "年轻人", "老年人", "中国人", "业内人士", "工作人员"}
GENERIC = {"everyone", "someone", "anyone", "everybody", "somebody", "nobody", "anybody",
           "others", "adults", "adult", "individuals", "folks", "persons", "personas"}


def strength(s):
    w = s.strip().lower()
    if s in ("人", "⼈"):
        return -5.0  # the bare word for a person
    if s in ROLE_NOUNS:
        return -1.0
    if "人" in s or "⼈" in s:  # compounds: 的人, 人的, 有人, 人员, ...
        return -2.5
    if "human" in w:
        return -3.5
    if "people" in w:
        return -2.2
    if w.startswith("personal") or w.startswith("personn") or w.startswith("personality"):
        return -1.3
    if "person" in w:
        return -2.3
    if w in HUMAN_WORDS:
        return -2.3
    if "user" in w or w in GENERIC:
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    return carry, strength(prefix.token_strings[-1])

