READS = ()


def of_value(previous):
    word = previous.strip().lower().lstrip('-')
    if word == '%':
        return -10.35 if previous == '%' else -8.25
    if word == 'percent':
        return -9.5
    if word in {'percentage', 'half', 'thirds', 'cent'}:
        return -6.4
    if word in {'majority', 'most', 'quarter', 'quarters'}:
        return -5.0
    if word in {'lot', 'proportion'}:
        return -4.25
    if word in {'fraction', 'portion', 'lots', 'many', 'few', 'several', 'none',
                'third', 'fourth', 'fifth', 'tenth', 'minority'}:
        return -2.95
    if word in {'some', 'much', 'plenty', 'rest', 'bulk', 'handful'}:
        return -2.4
    if word.isdigit() or word in {
            'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
            'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen',
            'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty'}:
        return -2.1
    if word in {'hundreds', 'thousands', 'millions', 'billions', 'tens'}:
        return -1.5
    if word in {'any', 'all', 'both', 'more', 'enough', 'best', 'worst'}:
        return -0.85
    if word in {'part', 'parts', 'amount', 'amounts', 'quantity', 'bit', 'ratio'}:
        return -0.65
    if word in {'year', 'years', 'month', 'months', 'hour', 'hours',
                'decade', 'decades', 'day', 'days', 'minute', 'minutes',
                'second', 'seconds', 'pounds', 'ounces', 'grams', 'miles',
                'hectares', 'acres', 'tons', 'tonnes', 'feet', 'liters',
                'litres', 'g', 'kg', 'mg', 'ml', 'lb', 'cc', 'cf'}:
        return -1.1
    if word in {'section', 'sections', 'subset', 'subsets', 'sample',
                'samples', 'portions', 'plurality', 'bunch'}:
        return -1.2
    if word in {'middle', 'midpoint', 'center', 'centre', 'north', 'west',
                'east', 'northeast', 'northwest', 'southeast', 'southwest'}:
        return -1.2
    if word in {'top', 'bottom', 'end', 'south'}:
        return -0.5
    if word == 'regardless':
        return 1.9
    if word in {'rid', 'capable', 'made', 'given', 'accused', 'convicted', 'died'}:
        return 1.2
    if word in {'is', 'are', 'be', 'was', 'were', 'whether', 'either',
                'probably', 'inside'}:
        return 0.9
    if word in {'expression', 'creation', 'invention', 'emergence',
                'appearance', 'birth', 'departure', 'work', 'works'}:
        return 0.8
    if word in {'advantage', 'course', 'sort', 'charge'}:
        return 0.9
    if word in {'instead', 'aware', 'proud', 'composed', 'consisted',
                'comprised', 'result', 'results'}:
        return 0.55
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word == 'of' or token == '-of':
        value = of_value(previous)
    elif token in {'s', 'd', 'f', 'v'} and previous.endswith('%'):
        value = {'s': -4.45, 'd': -3.4, 'f': -0.95, 'v': -0.5}[token]
