"""Component layers.0.mlp.down_proj:4438 -- a "share of" / percent detector.

Near zero almost everywhere. It goes strongly negative on the word that follows a
percentage: the "of" (or Spanish/German "de"/"der") in "10% of", "90 percent of",
and, more weakly, on the "of" in quantity phrases such as "most of", "half of",
"a lot of", "some of". It is also strongly negative on printf-style format letters
after "%" ("%s", "%d"), and mildly negative on the "%" sign itself. Other "of"
phrases, and everything else, get 0.
"""

READS = ()

PERCENT = {"%", " %", " percent", " cent", "percent", "-percent", "percentage", " percentage"}
SHARE_WORDS = {
    " majority", " most", " Most", " half", " lot", " lots", " proportion", " fraction",
    " portion", " many", " much", " rest", " some", " Some", " none", " None",
    " two", " three", " four", " five", " bulk", " plenty", " handful", " few",
}
WEAK_WORDS = {" amount", " part", " any", " all", " All", " top", " thousands", " center", " section"}
OF_WORDS = {" of", " de", " der"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if len(toks) < 2:
        return None, 0.0
    before = toks[-2]
    if before == "%" and tok in ("s", "d"):
        return None, -4.0
    if tok == "%":
        return None, -0.9
    if tok in OF_WORDS:
        if before in PERCENT:
            return None, -10.0
        if before in SHARE_WORDS:
            return None, -3.0
        if before in WEAK_WORDS:
            return None, -0.8
        if before in (" regardless", " rid", " died", " track"):
            return None, 1.5
        return None, 0.0
    return None, 0.0

