TEMPORAL_FORMS = {
    'temporary': 5.1,
    'temporarily': 3.8,
    'tempfile': 3.0,
    'temporal': 2.4,
    'tempor': 2.4,
    'orarily': 2.5,
    'makeshift': 1.4,
    'momentarily': 1.4,
    'tempo': 1.6,
    'temps': 1.3,
}
