    # Chinese temporary words and fragments (both writing systems).
    '临时': 3.9, '臨時': 3.9,
    '暂时': 3.0, '暫時': 3.0,
    '临': 1.3, '臨': 1.5,
    '暂': 1.3, '暫': 1.3,
    # Temperature, employment, permanence, and potentiality in Chinese.
    '温': 1.65, '溫': 1.0,
    '温度': 0.8, '溫度': 0.8,
    '员工': 0.8, '員工': 0.8,
    '永久': 1.1,
    '潜在': 1.65,
    # Russian temporal stems and Spanish 'time'.
    'врем': 2.1, 'времен': 2.45,
    'tiempo': 0.85,
}
OCCURRENCE = {'second', 'last', 'each', 'every', 'one', 'next'}
LOW_TIME_MODIFIERS = {'same', 'this', 'any', 'long', 'hard'}
ACCESS_MODIFIERS = {'public', 'private', 'protected', 'internal'}


def lexical_value(token, previous=''):
    bare = token.strip()
    word = bare.lstrip('._-/([{=,:"\'$').lower()
