        return TEMPORAL_FORMS[word]
    if word in TRANSLATED_CUES:
        return TRANSLATED_CUES[word]
    if word == 'emporary':
        return 1.0 if previous.endswith('cont') else 2.9
    if word == 'temp':
        if bare.startswith(('(', '[', '=')):
            return 3.6
        if bare.isupper():
            return 4.0
        if bare.startswith('_') or token.startswith(' Temp'):
            return 5.3
        return 4.9 if 'T' in bare else 4.5
    if word == 'tmp':
        if token == 'tmp':
            return 2.65
        return 1.85 if bare.startswith(('(', '=', '/')) else 2.2
    if word == 'potential':
        return 1.6 if token[:1].isspace() else 1.25
    if word.startswith('potential'):
        return 0.67
    if word == 'time':
        if previous == 'first':
            return 0.06
        if previous in OCCURRENCE:
            return 0.20
        if previous in LOW_TIME_MODIFIERS:
            return 0.26
        return 0.86 if bare.startswith(('-', '.')) else 0.70
    if word == 'times':
        return 0.12
    if word.startswith(('timeout', 'timed', 'timezone', 'datetime')):
        return 0.35
    if word.startswith(('permanent', 'transient')):
        return 1.0
    if word == 'static':
        if 'Static' in bare:
            return 0.53
        return 1.12 if previous in ACCESS_MODIFIERS else 0.72
    if word in {'dynamic', 'dynamically', 'ynamic'}:
        return 0.9
