"""A local detector for 'then', 'than', and related linking expressions.

Predict negative activation on sequencing, consequence, and comparison
markers, including several translations and Chinese character pieces.
A preceding comma strengthens 'then'; local temporal cues weaken it.
'Than' is nearly silent after 'more/less/rather/other', intermediate after
-er comparatives, and stronger otherwise. Unlisted responses are omitted.
"""

READS = ()

# Consequence/conditional expressions, not an unrestricted word vocabulary.
LINKERS = {
    'otherwise': -0.7, 'dann': -1.0, 'thì': -1.6,
    'то': -1.4, 'тогда': -1.5, 'alors': -0.8,
    'entonces': -2.0, 'então': -1.0, 'maka': -1.8, 'ise': -0.9,
    'なら': -0.9, 'すると': -1.0, '的话': -1.1, '的話': -1.3,
}

# Chinese 'then', 'otherwise', and their lexical character pieces.
CHINESE = {
    '则': -6.0, '則': -6.0, '，则': -5.2, '，則': -5.2,
    '那么': -3.7, '那麼': -2.8, '那': -1.6,
    '则是': -3.3, '則是': -3.3,
    '然后': -0.6, '然後': -0.6, '否则': -1.2, '否則': -1.7,
    '不然': -1.3, '么': -1.3, '麼': -1.1, '麽': -1.1,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word, prev = raw.strip(), previous.strip().lower()
    if word == '\ufffd' and previous:
        # A byte-fragment token can complete one of these Chinese characters.
        tail = prefix.text_prefixes[-1][-1:]
        if tail in {'则', '那'}:
            value = -6.8 if tail == '则' else -1.3
            return (doc, raw), value
    lower = word.lower()
    value = 0.0
    if lower == 'then':
        value = -2.0 if ',' in previous else -1.55
        if prev in {'and', 'since'}:
            value = -1.25
        elif prev == 'but':
            value = -1.4
        elif prev in {'was', 'were', 'had', 'he', 'i', 'by', 'even'}:
            value = -1.1
    elif lower == 'than':
        if prev in {'more', 'less', 'rather', 'other'}:
            value = 0.0
        else:
            value = -1.0 if prev.endswith('er') or prev == 'worse' else -1.8
    elif lower == 'so':
        if word == 'So' or ',' in previous or '\n' in previous:
            value = -0.3
    elif lower == 'therefore':
        value = -0.4 if word[0].isupper() else -0.2
    elif lower in {'thus', 'hence'}:
        if word[0].isupper():
            value = -0.2
        elif ',' in previous:
            value = -0.1
    elif word in CHINESE:
        value = CHINESE[word]
    elif word.startswith('那') or word.endswith(('则', '則')):
        value = -1.0
    elif word in {'所以', '因此', '于是', '於是'}:
        value = -0.3
    elif word.endswith('면'):
        value = -0.9 if word == '면' else -1.3
    elif word.endswith(('れば', 'たら')):
        value = -0.7
    elif lower in LINKERS:
        # Leading spaces distinguish whole Western words from suffix pieces.
        if raw[:1].isspace() or word in {'なら', 'すると', '的话', '的話'}:
            value = LINKERS[lower]
    return (doc, raw), value

