"""Estimate activity for a small set of sequence, comparison, and result words.

Most positions are quiet. The estimates are negative on words such as “then”
and “than,” and especially large on the Chinese sequence/result markers.
"""

READS = ()

SEQUENCE_WORDS = {"then"}
OTHER_SEQUENCE_WORDS = {"dann", "тогда", "然後", "然后"}
COMPARISON_WORDS = {"than"}
RESULT_WORDS = {"so", "therefore", "otherwise"}
CONDITION_WORDS = {"thì", "면", "れば", "すると"}
EDGE_PUNCTUATION = " \t\r\n,.;:!?\"'`()[]{}<>“”‘’"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(EDGE_PUNCTUATION).casefold()
    if word == "则":
        return None, -5.6
    if word == "那么":
        return None, -4.1
    if word in SEQUENCE_WORDS:
        return None, -1.55
    if word in COMPARISON_WORDS:
        return None, -0.63
    if word in OTHER_SEQUENCE_WORDS:
        return None, -1.0
    if word in RESULT_WORDS:
        value = {"so": -0.28, "therefore": -0.38,
                 "otherwise": -0.65}[word]
        return None, value
    if word in CONDITION_WORDS:
        return None, -0.9
    return None, 0.0

