"""Sparse empirical phrase rules, not a complete lexical model.

Quote-header words, self-corrections, Java and mathematical notation have
negative responses; selecting an object and Python decorator names have
positive ones. Smaller grammatical and punctuation/byte-fragment rules
fill in common responses. Document-local flags remember symbolic 'a' and
Wait/Hmm/Alternatively, adjusting later articles and checking/example
words. Unmodeled token-specific variation is deliberately left at zero.
"""
READS = ()

CHECKING = frozenset({
    'original', 'after', 'calculation', 'calculations', 'computed',
    'correct', 'correctly', 'code', 'result', 'thinking', 'carefully',
    'output', 'rhs', 'wrong', 'understand', 'since',
})
EXPLORING = frozenset({
    'another', 'some', 'example', 'common', 'useful', 'knowledge',
})


def local_response(token, previous):
    w, p = token.strip().lower(), previous.strip().lower()
    # Forum attribution headers.
    if token.strip() == 'Posted':
        return -0.48 if p == 'originally' else -0.13
    if w == 'by' and previous.strip() == 'Posted':
        return -0.22
    if token.strip() in {'Quote', 'Originally', 'Posts'}:
        return -0.09
    if token.lstrip().startswith(':') and p in {'quote', 'explanation'}:
        return -0.08 if p == 'quote' else -0.24
    # Programming names and syntax.
    if w == 'staticmethod':
        return 0.46
    if w == 'classmethod':
        return 0.22
    if w in {'java', '.java'}:
        return -0.12
    if w == '#include':
        return -0.10
    if token == 'import':
        return -0.04 if ';' in previous else 0.10
    if w in {'def', '@'}:
        return 0.05
    # Explicit self-correction and mathematical notation.
    if w == 'misunderstanding':
        return -0.52 if p == 'my' else -0.28
    if w in {'misunderstood', 'typo', 'messed'}:
        return -0.21
    if w == 'understand':
        return -0.14 if p in {'i', 'me', "'t", "n't"} else -0.04
    if p == 'my' and w in {'calculations', 'calculation', 'interpretation', 'code'}:
        return -0.22
    if w in {'numerator', 'denominator', 'denote', 'rhs'}:
        return -0.16
    # Articles: choosing a new object versus describing an existing one.
    if w in {'a', 'an'}:
        if p in {'write', 'need', 'pick', 'choose', 'try', 'let'}:
            return 0.24
        if p in {'find', 'want', 'set', 'make', 'made', 'get', 'form', 'do'}:
            return 0.09
        if p in {'was', 'been', 'being', 'having', 'owning', 'owned'}:
            return -0.06
        if p in {'has', 'had', 'using', 'into', 'without', 'for', 'than'}:
            return -0.03
        if p in {'if', 'when', 'that', 'like', 'after', "'s", ':', '='}:
            return 0.08
        return 0.01
    # Short grammatical phrases.
    if w == 'me' and p == 'let':
        return 0.10 if previous.strip() == 'Let' else 0.04
    if w == 'some':
        return -0.06 if p in {'for', 'in', 'to', 'and', ','} else -0.01
    if w == 'many' and p == 'how':
        return 0.12
    if w == 'of':
        if p == 'because':
            return 0.14
        if p in {'one', 'some', 'most', 'any', 'each', 'set', 'type', 'types'}:
            return 0.075
        if p in {'result', 'value', 'length', 'name', 'department', 'instance'}:
            return -0.08
    if w == 'to' and p in {'how', 'try', 'prior', 'access'}:
        return 0.08
    if w == 'to' and p in {'according', 'response'}:
        return -0.075
    if w == 'as' and p in {'same', 'long', 'far', 'much', 'soon', 'written'}:
        return -0.11
    # Quantifiers, ordering, prepositions and discourse markers.
    if w in {'one', 'all', 'each', 'first'}:
        return 0.04
    if w in {'other', 'others', 'either', 'nothing', 'next'}:
        return -0.055
    if w in {'under', 'through', 'along', 'per', 'because'}:
        return -0.04
    if w in {'always', 'often', 'still'}:
        return -0.06
    if w == 'alternatively':
        return 0.085
    if w in {'until', 'unless', 'thus'}:
        return 0.05
    if w in {'was', 'had', 'used'}:
        return 0.025
    if w == 'the':
        return -0.006
    if '\ufffd' in token:
        return 0.027
    if token in {"'", '’', '\\'}:
        return -0.03
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, variable_a, exploring = '', False, False
    else:
        _, previous, variable_a, exploring = carry
    word = token.strip().lower()
    value = local_response(token, previous)
    if token == ' a' and variable_a:
        value += 0.10
    if exploring:
        if word in {'a', 'an'} and token.startswith(' '):
            value += 0.035
        if word in CHECKING:
            value -= 0.12
        if word in EXPLORING:
            value += 0.23
    # Remember only evidence already encountered in this document.
    if previous.strip().lower() == 'a' and any(c in token for c in '=+^_'):
        variable_a = True
    if token == ' a' and previous.strip().lower() == 'let':
        variable_a = True
    if token.strip() in {'Wait', 'Hmm', 'Alternatively'}:
        exploring = True
    return (doc, token, variable_a, exploring), float(value)

