"""Layer-0 MLP down_proj component 4443 (a weak, mostly token-level feature).

What it does, in plain terms (values fitted on a few thousand training rows):
1. Indefinite article after a verb of choosing/writing/making ("Write a", "pick a",
   "choose an", "need a"): positive. After a verb of being or having ("was a",
   "having a", "been a"): slightly negative.
2. Quantity and order words: "one", "first", "all", "exactly", "another" slightly
   positive; "other", "next", "some", "no", "always" slightly negative.
3. Programming-language and library names (java, .java, .Println, http, www, lib,
   template): negative. Code idioms (init, @Override, staticmethod, decorators,
   def): positive.
4. Forum quote header "Originally Posted by" (the word "Posted") and self-doubt words
   ("misunderstanding", "messed", "mistake"): strongly negative.
Everything else predicts 0.
"""

READS = ()

CREATE_VERBS = {"write", "pick", "choose", "need", "want", "set", "try", "find",
                "create", "make", "get", "start", "give", "design", "construct",
                "define", "compute", "prove", "show", "consider", "Write", "Pick",
                "Choose", "Find", "Let", "Give", "Create"}
BE_HAVE_VERBS = {"was", "were", "been", "being", "having", "has", "had", "using"}
ARTICLES = {"a", "an"}
ORDER_POS = {"one", "first", "all", "exactly", "another", "top", "major", "mostly",
             "overall", "common", "rare"}
ORDER_NEG = {"other", "next", "some", "no", "always", "after", "just", "under"}
CODE_NAMES_NEG = {"java", ".java", ".Println", "_replace", "template", "#include",
                  "equals", "lib", "http", "www", ".api", "Exception"}
CODE_IDIOMS_POS = {"init", "@Override", "mut", "staticmethod", "@", ".println", "def"}
FORUM_NEG = {"Posted", "misunderstanding", "messed", "mistake"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if tok in ARTICLES:
        if prev in CREATE_VERBS:
            return None, 0.16
        if prev in BE_HAVE_VERBS:
