    if tok in CODE_NAMES_NEG:
        return None, -0.08
    if tok in CODE_IDIOMS_POS:
        return None, 0.05
    if tok in ORDER_POS:
        return None, 0.03
    if tok in ORDER_NEG:
        return None, -0.03
    return None, 0.0

