NBSP = "\N{NO-BREAK SPACE}"
PROOF_MARKER = re.compile(
    r'Metamath|Logic Explorer|StepHypRef|Ref Expression|Syntax hints:|'
    r'Colors of variables:|Definitiondf|Syntaxc[a-z]|'
    r'\b(?:df|ax)-[a-z0-9]'
)

# Field names on proof-explorer pages, not general prose vocabulary.
PROOF_FIELDS = {
    'Syntax': -1.4,
    'Definition': -1.3,
    'Explorer': -5.0,
    'referenced': -6.0,
    'hints': -5.5,
}


@lru_cache(maxsize=4096)
def typography(token):
    styled = any(c.isalpha() and
                 'MATHEMATICAL' in unicodedata.name(c, '') for c in token)
    return (token == NBSP, token == ' .', styled,
            any(c in token for c in '∈∧↔⊢'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', False, '', deque(), [0, 0, 0, 0])
    _, recent, formal, previous, history, counts = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    text = recent + token
    n_spaces, n_dots, n_letters, n_logic = counts
    formal = formal or bool(PROOF_MARKER.search(text))
    formal = formal or (n_spaces >= 2 and
                        (n_dots >= 2 or n_letters >= 2 or n_logic >= 3))

    flags = typography(token)
    styled_math = n_letters > 0 or flags[2]
    strong_math = formal or styled_math

    if token == NBSP:
        value = -4.1 if styled_math else -3.15 if formal else -1.0
        if not strong_math and n_spaces >= 2:
            value -= 0.15
        if previous == ' ':
            value -= 0.7
        elif previous[-1:].isdigit() and not strong_math:
            value -= 0.4
        elif NBSP in previous:
            value += 0.5
        if formal and (' > ' in recent[-25:] or 'Mirrors' in recent[-25:]):
            value = -8.3
    elif NBSP in token:
        value = -0.35 if token.isspace() and '\n' not in token else -0.05
    elif token == ' .':
        if styled_math:
            value = -6.9
        elif formal and (previous == ' .' or previous[-1:].isdigit()):
            value = -5.0
        else:
            value = -0.8 if previous == ' .' else -0.08
    # Metamath uses df- for definitions and ax- for axioms.
    elif word == 'df':
        if text.endswith('Definitiondf'):
            value = -4.8
        elif previous == NBSP:
            value = -8.1
        else:
            value = -1.6 if token.startswith(' ') else -1.2
    elif word == 'ax':
        value = -5.0 if previous == NBSP else -0.25
    # 'Theorem' often ends with a separate 'orem' token.
    elif word in {'theorem', 'Theorem', 'orem'}:
        value = -7.2 if formal else (-2.6 if token == 'theorem' else -1.5)
        if not formal and 'Proof of The' in text[-30:]:
            value = -2.7
    # The plural can be split as The + ore + ms.
    elif word == 'ore' and recent.lower().endswith('the'):
        value = -4.3 if formal else -0.35
    elif word == 'ms' and recent.lower().endswith('theore'):
        value = -1.6 if formal else -0.2
    elif word == 'uted' and recent.lower().endswith('contrib'):
        value = -3.1 if formal else -0.1
    elif formal and word in PROOF_FIELDS:
        value = PROOF_FIELDS[word]
    elif word.lower() in {'lemma', 'lem', 'tactic', 'simp'}:
        value = -0.8
    elif word == 'induction':
        value = -0.3
    elif '->' in token:
        value = -0.47
    elif '→' in token:
        value = -4.0 if strong_math else (-0.3 if token.startswith(' ') else -0.17)
    elif '∈' in token:
        value = -4.7 if strong_math else (-0.3 if token.startswith(' ') else -0.06)
    elif '∧' in token:
        value = -4.3 if strong_math else -0.95
    elif '↔' in token:
        value = -5.2 if strong_math else -2.5
    elif '⊢' in token:
        value = -2.5
    elif '∀' in token or word == 'forall':
        value = -1.0
    elif any(c in token for c in 'ℝℕℂ'):
        value = -1.7
    elif token == '‘':
        value = -4.7 if strong_math else -0.15
    elif '=>' in token:
        value = -0.15
    elif word == 'Expression':
        value = -8.0 if formal else -0.35
    elif (token.startswith(' ') and len(word) >= 2
          and set(word) == {'('}):
        value = -2.5 if strong_math else -0.55
    elif flags[2]:
        value = -1.6 if any(c.isupper() for c in token) else -0.65
    elif token == ' ,':
        value = 0.24
    else:
        value = 0.0

    # Sliding counts: isolated NBSP, spaced dot, styled letter, logic symbol.
    if len(history) == 64:
        old = history.popleft()
        for i in range(4):
            counts[i] -= old[i]
    history.append(flags)
    for i in range(4):
        counts[i] += flags[i]
    return (doc, text[-220:], formal, token, history, counts), value

