    if lower in {'nuclear', 'uclear'}:
        return 3.03 if lower == 'nuclear' else 2.63
    if lower in {'nucle', 'ucle', 'nucleus', 'nuclei'}:
        return 1.45 if lower == 'nuclei' else 1.8
    if lower == 'cores':
        return 1.6 if token.startswith(' ') else 0.6
    # Chinese nucleus/core words, then related soul/core/shell characters.
    if word == '核':
