"""A sparse detector for dep spellings and a few plain-language relatives."""
READS = ()

RELIANCE_WORDS = {
    "rely", "relies", "relied", "relying", "reliance",
    "依靠", "靠", "依赖", "依存", "取决",
}
PART_WORDS = {"部分", "科"}

def last_word(text):
    word = ""
    for char in text.casefold():
        if char.isalpha():
            word += char
        else:
            word = ""
    return word

def step(carry, prefix, upstream):
    """Pulse on dep spellings, dependence synonyms, and department-of phrases."""
    doc = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1].casefold()
    word = token.strip()
    if "dep" in token:
        value = -1.7
    elif word in RELIANCE_WORDS:
        value = -0.8 if word.isascii() else -0.55
    elif word in PART_WORDS:
        value = -0.65
    elif word == "endent" and previous == "dep":
        value = -1.7
    elif word == "ploy" and previous == "de":
        value = -0.5
    elif word == "of" and previous in {"department", "departments", "dept"}:
        value = -1.5
    else:
        value = 0.0
    return (doc, last_word(token)), value

programs.sol:
"""Recognize a vowel-led continuation of a consonant-only word opening.

Short completions such as 'G' + 'op' or 'Л' + 'он' get positive values.
Two-letter closed completions are strongest; long continuations and
multi-consonant openings are weaker. Word-internal splits are attenuated.
This is a letter-shape rule, not a dictionary of individual token spellings.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouаеёиоуыэюяіїєاوي')
H_DIGRAPHS = frozenset(('ch', 'sh', 'th', 'ph', 'wh', 'kh', 'zh'))


def is_vowel(c):
    return unicodedata.normalize('NFD', c.lower())[0] in VOWELS


def known_alphabet(c):
    return unicodedata.name(c, '').startswith(('LATIN', 'CYRILLIC', 'ARABIC'))


def opening_fragment(text):
    tail = ''
    for c in text:
        if not c.isalpha():
            tail = ''
        elif c.isupper() and tail and tail[-1].islower():
            tail = c
        else:
            tail += c
    return tail


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    fragment, fresh, previous_ends_letter = '', True, False
    if carry is not None and carry[0] == doc:
        _, fragment, fresh, previous_ends_letter = carry

    # Remember this token's final word fragment and whether it starts a word.
    tail = opening_fragment(token)
    new_fresh = (not previous_ends_letter or len(tail) < len(token)
                 or len(tail) == 1 and tail.isupper())
    state = (doc, tail, new_fresh, bool(token and token[-1].isalpha()))

    if not (token.isalpha() and known_alphabet(token[0])
            and 1 <= len(fragment) <= 3
            and all(known_alphabet(c) for c in fragment)
            and (fragment.lower() == 'qu'
                 or not any(is_vowel(c) for c in fragment))):
        return state, 0.0
    initial = token[0].lower()
    if not (is_vowel(initial) or initial == 'y'):
        return state, 0.0

    n = len(token)
    closed = not (is_vowel(token[-1]) or token[-1].lower() == 'y')
    if n == 1:
        value = 0.40
    elif n == 2:
        value = 0.72 if closed else 0.46
    elif n == 3:
        value = 0.36 if closed else 0.22
    else:
        value = 0.08 if n == 4 else 0.02
    if not fresh:
        value *= 0.45
    # Common digraphs behave more like one consonant than arbitrary clusters.
    if fragment.lower() in H_DIGRAPHS:
        value *= 0.67
    elif fragment.lower() == 'sch':
        value *= 0.40
    elif len(fragment) == 2:
        value *= 0.34 if n <= 2 else 0.17
    elif len(fragment) == 3:
        value *= 0.10
    if n >= 2 and not ('a' <= initial <= 'z'):
        value *= 0.75 if '\u0400' <= initial <= '\u052f' else 0.45
    if initial == 'y':
        value *= 0.65
    return state, value

programs.luna:
"""A text-surface estimate built from the current token and its three immediate
predecessors. It favors digit tokens and number words, penalizes coordinating
words, and responds to nearby punctuation and broad token shapes. It is a coarse
predictor, not a lookup table of token IDs.
"""

READS = ()

COORDINATORS = {
    "and", "or", "but", "nor", "yet", "so",
}
NEGATIONS = {"not", "no", "never", "neither", "without"}
NUMBER_WORDS = {
    "zero", "one", "two", "three", "four", "five", "six", "seven",
    "eight", "nine", "ten", "hundred", "thousand", "million",
    "first", "second", "third",
}

# A coarse spelling class, not a token-ID lookup.
def token_type(text):
    text = text.strip()
    if not text:
        return "space"
    if text.isdigit():
        return "digit"
    if text.isalpha():
        return "alpha"
    if all(not ch.isalnum() and not ch.isspace() for ch in text):
        return "punct"
    if any(ch.isdigit() for ch in text):
        return "mixed_digit"
    return "mixed"


CURRENT_TYPE = {
    "alpha": 0.0,
    "digit": 0.01651,
    "mixed": 0.00057,
    "punct": -0.00669,
    "space": -0.00912,
}
PREVIOUS_TYPE = {
    "alpha": 0.01397,
    "digit": -0.00876,
    "mixed": -0.00254,
    "punct": 0.01565,
    "space": 0.00176,
}
TWO_BACK_TYPE = {
    "alpha": -0.03669,
    "digit": 0.00140,
    "mixed": -0.03472,
    "punct": -0.03217,
    "space": -0.03162,
}
THREE_BACK_TYPE = {
    "alpha": 0.03428,
    "digit": 0.02947,
    "mixed": 0.03384,
    "punct": 0.03821,
    "space": 0.03040,
}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    stripped = text.strip()
    lower = stripped.lower()
    kind = token_type(text)

    # The class and digit cues overlap for a digit token; mixed digit strings
    # get the digit cue too.
    value = -0.01320 + CURRENT_TYPE.get(kind, 0.0)
    if any(ch.isdigit() for ch in stripped):
        value += 0.01651
    if lower in COORDINATORS:
        value -= 0.03756
    if lower in NEGATIONS:
        value -= 0.01051
    if lower in NUMBER_WORDS:
        value += 0.02735

    # Only use a predecessor from the same document.
    t = len(prefix.token_ids) - 1
    if t > 0 and prefix.document_ids[t] == prefix.document_ids[t - 1]:
        previous = prefix.token_strings[t - 1]
        previous_stripped = previous.strip()
        previous_kind = token_type(previous)
        value += PREVIOUS_TYPE.get(previous_kind, 0.0)
        if any(ch.isdigit() for ch in previous_stripped):
            value -= 0.00876
        if previous_stripped.startswith((",", "，")):
            value -= 0.00437
        if previous_stripped.startswith((".", "。")):
            value += 0.07603
        if "\n" in previous or "\r" in previous:
            value -= 0.01011

    # Two- and three-token context contribute only their broad spelling class.
    for back, weights in ((2, TWO_BACK_TYPE), (3, THREE_BACK_TYPE)):
        earlier = t - back
        if earlier >= 0 and prefix.document_ids[earlier] == prefix.document_ids[t]:
            value += weights.get(token_type(prefix.token_strings[earlier]), 0.0)

    return None, float(value)

programs.sol:
"""Approximate the component's large responses to source-code comments.

Single hashes and double slashes respond most after indentation or code.
Hashes in prose/links and Markdown headings do not get that large response.
Empty comments and documentation-comment syntax have separate small values.
Keep 400 recent characters and the previous token, resetting per document.
This models the comment-related peaks, not the smaller lexical fluctuations.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent, previous = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    mark = token.strip()
    line = recent.rsplit('\n', 1)[-1]
    indented = bool(line) and line.isspace()
    spacing = previous.isspace() and '\n' not in previous
    python_code = bool(re.search(r'\b(import|from|def|return|print)\b', recent))
    code = python_code or any(c in recent for c in '{};=')
    closes_code = previous.rstrip().endswith((')', ']', "'", '"'))
    leading_space = token.startswith(' ')
    value = 0.0

    if mark == '#':
        value = 0.04 if leading_space else 0.06
        if first:
            value = -0.03
        elif spacing and leading_space:
            value = (0.49 if '\t' in previous else 0.56) + 0.05 * indented
        elif leading_space and closes_code:
            value = 0.52
        elif not leading_space:
            if previous.endswith('\t'):
                value = 0.43
            elif previous.endswith('\n'):
                value = 0.58 if python_code else 0.52 if closes_code else 0.17
                if code and not (python_code or closes_code):
                    value = 0.35
            elif indented:
                value = 0.50
            elif previous.endswith(('](', '.md', '.html')):
                value = -0.06
    elif re.fullmatch(r'[;)}{]*//#?', mark):
        value = 0.50 if leading_space else 0.38
        if first:
            value = 0.55 if token == '//' else 0.30
        elif indented:
            value = 0.64
        elif spacing:
            value = 0.51
        elif (previous.rstrip().endswith(';')
              or (previous.endswith('\n') and closes_code)):
            value = 0.60
        elif previous.rstrip().endswith(':'):
            value = 0.20
        elif leading_space and closes_code:
            value = 0.42
        elif leading_space and not code:
            value = 0.32
    elif mark.startswith(('/**', '/*!')):
        value = -0.11
    elif mark == '/*':
        value = 0.15 if leading_space else 0.08
    elif mark == '///':
        value = 0.08 if leading_space else -0.03
    elif mark == '#include':
        value = -0.15
    elif mark == 'import':
        value = -0.09

    if mark in ('#', '//') and '\n' in token:
        value = 0.03  # Empty line comment.
    elif re.fullmatch(r'//[-=]{4,}', mark):
        value = 0.22  # Decorative comment separator.
    elif re.fullmatch(r'#{4,}', mark):
        value = 0.15
    elif re.fullmatch(r'#[=-]{4,}', mark):
        value = 0.42
    return (doc, (recent + token)[-400:], token), float(value)

"""Approximate a chat-structure signal, strongest at message/thought/tool tags.

Message ends following a tool delimiter are stronger than ordinary sentence
ends. A message start at the start of a document is slightly weaker. Outside
these structural markers, character classes approximate the small remainder:
letters have a mildly negative response, whereas
numbers, whitespace, and punctuation are close to zero.
