READS = ()

BOUNDARIES = {
    '<|im_start|>': 1.44,
    '<think>': 1.30,
    '</think>': 1.50,
    '<tool_call>': 1.30,
    '</tool_call>': 1.27,
    '<tool_response>': 1.22,
    '</tool_response>': 1.96,
    '<|endoftext|>': 0.01,
