        if previous == '</tool_response>':
            value = 2.27
        elif previous == '</tool_call>':
            value = 2.22
        elif previous.rstrip().endswith(('.', '?', '。', '？')):
            value = 1.92
        else:
            value = 2.04
    elif token == '<|im_start|>' and previous in ('', '<|endoftext|>'):
        value = 1.37
    elif value is None:
        if not text or text.isdigit():
            value = -0.003
        elif not any(c.isalnum() for c in text):
            value = -0.006
        elif any('\u0400' <= c <= '\u052f' or '\u0600' <= c <= '\u06ff'
                 for c in text):
            value = -0.05
        elif any('\u4e00' <= c <= '\u9fff' for c in text):
            value = -0.028
        elif not text.isascii():
            value = -0.04
        elif text.isalpha():
            value = -0.017 if len(text) <= 2 else -0.025
        else:
            value = -0.016
    return (doc, token), float(value)

"""A token-form detector for question marks, not whole question sentences.

It predicts a large negative response to ASCII, fullwidth, and Arabic
question marks. Attached newlines or closing punctuation weaken it;
closely spaced marks also weaken it. Common forms respond more strongly
early in a document. A few East Asian question endings and the keyword
await have smaller negative responses. Other tokens are predicted as zero.
"""
from math import exp

READS = ()
MARKS = frozenset('?？؟')
PARTICLES = {
    '吗': -0.85, '嗎': -0.71, '了吗': -1.15, '呢': -0.61,
    'か': -0.44, '냐': -1.2,
}
JAPANESE_QUESTION_ENDINGS = {
    'のか', 'なのか', 'ですか', 'でしょうか', 'のでしょうか',
}


def strength(token, position):
    count = sum(c in MARKS for c in token)
    if count > 1:
        value = 1.65 if count <= 3 else 1.3
        if token.startswith(' '):
            value += 0.3
        return value * (0.6 if '\n' in token else 1.0)
    i = next(i for i, c in enumerate(token) if c in MARKS)
    before, mark, after = token[:i], token[i], token[i + 1:]
    early = exp(-position / 64.0)
    # Tag delimiters differ from terminal question marks.
    if '<' in before or '>' in after:
        return 0.65 if '\n' in after else 1.2
    if not after.strip():
        lines = after.count('\n')
        if not lines:
            value = (2.65 + 0.65 * early if mark == '？'
                     else 3.24 + 0.95 * early)
            value *= 0.5 if position == 0 else 1.0
        elif mark == '？':
            value = 1.4 + 0.5 * early
        elif lines == 1:
            value = 1.61 + 0.62 * early
        else:
            value = 1.48 + 0.4 * exp(-position / 96.0)
        value += 0.3 if before.strip() else 0.2 if before else 0.0
        return 4.8 if before.endswith('/') and not lines else value
    if ';' in after and '\n' in after:
        return 2.65
    if '\n' in after:
        return 1.05 if after.count('\n') == 1 else 0.9
    if after == ')' or after.startswith(('(', '[')):
        return 2.4
    if after[0].isalpha() or after.startswith('\\'):
        return 2.8
    return 1.7


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    # Both position and punctuation history reset at document boundaries.
    if carry is None or carry[0] != doc:
        position, last = 0, -100
    else:
        position, last = carry[1] + 1, carry[2]
    if any(c in MARKS for c in token):
        value = strength(token, position)
        gap = position - last
        if gap == 1 and sum(c in MARKS for c in token) > 1:
            value = 0.0
        elif gap <= 6:
            value = max(0.0, value - (1.0 if gap == 1 else 0.4))
        last = position
        value = -value
    elif token in JAPANESE_QUESTION_ENDINGS:
        value = -1.05
    else:
        value = (-0.74 if token.strip() == 'await'
                 else PARTICLES.get(token, 0.0))
    return (doc, position, last), value

programs.luna:
"""Give question marks and common question particles their learned signal.

The component is nearly silent on ordinary tokens. It produces its strongest
negative responses at question marks; line breaks and closing punctuation
usually make that response smaller.
"""
READS = ()


def _question_mark(token, mark):
    """Estimate the response to one question mark from nearby punctuation."""
    before = token[:mark]
    after = token[mark + 1:]

    if "\n" in after:
        if after.startswith("\n"):
            return -1.6 if after.startswith("\n\n") else -1.8
        if after.endswith("\n\n"):
            return -0.8
        return -1.3
    if after.startswith(")"):
        return -2.35
    if after.startswith(('"', "'", "”", "’")):
        return -1.6
    if after.startswith((",", ".", ":")):
        return -1.7 if after[0] != ":" else -1.55
    if after.startswith("!"):
        return -1.95
    if after.startswith(">"):
        return -1.3
    if after.startswith("\\"):
        return -3.0

    if not after:
        if before.endswith(("'", '"', "”", "’")):
            return -4.0
        if before.endswith(")"):
            return -3.4 if before.endswith("))") else -3.7
        if token.startswith(" "):
            return -3.7
        return -3.4
    return -2.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "?" in token:
        if token.count("?") > 1:
            return None, -2.3
        mark = token.index("?")
        if token[:mark].endswith("<"):
            return None, -1.3
        return None, _question_mark(token, mark)

    for mark, ordinary_value in (("？", -2.75), ("؟", -3.2), ("¿", -0.43)):
        if mark in token:
            after = token.split(mark, 1)[1]
            if "\n" in after:
                return None, -1.6
            return None, ordinary_value

    particles = {
        "吗": -0.9,
        "嗎": -0.9,
        "呢": -0.62,
        "吧": -0.45,
        "か": -0.43,
        "냐": -1.45,
    }
    if token in particles:
        return None, particles[token]
    return None, 0.0

