            return -4.5
        if word != 'src':
            return -3.0 if token.startswith(' ') else -4.1
        if token.startswith('['):
            return -3.1
        if token.startswith(('(', '_', '-')):
            return -4.0
        if token.startswith('\t'):
            return -4.5
        if token.startswith(' '):
            return -6.5
        return -6.35 if token.startswith('/') else -5.9
    if lower == 'href':
        return -5.6 if token.startswith(' ') else -3.5
    if lower in {'arc', 'arcs'}:
        if word.isupper():
            return -1.2
        return -1.9 if lower == 'arcs' else -2.5
    if word == '弧':
        return -4.1
    if lower == 'rc':
        return -1.1 if token[:1].isspace() or token[:1] in '._-(' else -2.2
    if lower in {'ref', 'refs'}:
        return -0.7
    if lower == 'source':
        return -0.4
    if lower == 'lib':
        return -1.1 if token.startswith('/') else -0.6
    if lower == 'dist':
        return -0.5
    if token.startswith('/') and lower in {'bin', 'tests', 'java', 'pkg'}:
        return -0.6
    if token == 'tests':
        return -0.5
    if token == '/docs':
        return -0.4
    if lower in {'argv', 'argc'}:
        return -1.7 if lower == 'argc' else -1.1
    if word in {'rel', 'xmlns', 'onClick', 'onclick'}:
        return {'rel': -0.5, 'xmlns': -0.85,
                'onClick': -1.7, 'onclick': -0.9}[word]
    if token.startswith(' ') and lower in {'exit', 'stop', 'shut', 'disable'}:
        return {'exit': 0.33, 'stop': 0.25, 'shut': 0.58, 'disable': 0.45}[lower]
    if word in {'停', '停止', '关', '關', '关闭'}:
        return {'停': 1.4, '停止': 0.45, '关': 0.9, '關': 0.5, '关闭': 0.8}[word]
