        if previous.strip() in {'cd', 'find'}:
            return 0.53
        if previous.strip().isdigit() or previous.strip() in {')', ']'}:
            return 0.1
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), response(token, previous)

"""Detect separately tokenized ASCII spaces, with a left-context correction.

Responses are largest after operators, clause separators and words that
introduce numbers. Document/line starts, another standalone space and East
Asian text give weak responses. A logarithmic position factor makes responses
stronger near the start of a document. Other tokens stay near zero.
"""
from math import log1p

READS = ()
ARTICLES = set("a an the".split())
LINKS = set("and or".split())
DISCOURSE = set("but so yet nor".split())
FUNCTION_WORDS = set("""
as at by for from in into of on onto to with without than that which who
whose is are was were be been being have has had do does did can could may
might must will would shall should about after before between since until
around
""".split())
MONTHS = set("""
january february march april may june july august september october november
december
""".split())
REFERENCE_LABELS = set("figure fig page chapter section rule test example".split())
OPERATORS = set("+-=<>*/%~≈≠≤≥→×÷–—!&|")
SEPARATORS = {":": 1.91, ",": 1.85, ";": 1.40, ".": 1.10}


def east_asian(s):
    return any("\u3000" <= c <= "\u30ff" or
               "\u4e00" <= c <= "\u9fff" or
               "\uff01" <= c <= "\uff65" for c in s)


def space_value(previous):
    s = previous.strip()
    word = s.lower()
    if "\n" in previous or "\r" in previous:
        return -0.10
    if previous == " ":
        return -0.04
    if not s:
        if previous == "  ":
            return 0.85
        return 1.23 if previous == "   " else 1.15
    if east_asian(s):
        return 0.02
    if any("\u0e00" <= c <= "\u0e7f" for c in s):
        return 0.34
    if word in ARTICLES:
        return 1.50
    if word in LINKS:
        return 1.80
    if word in DISCOURSE:
        return 1.00
    if word in FUNCTION_WORDS:
        return 1.62
    if word in MONTHS or word in REFERENCE_LABELS:
        return 1.35
    if word == "return":
        return 1.95
    if word == "copyright" or s == "©":
        return 2.20
    if all(c in OPERATORS for c in s):
        if not previous.startswith(" "):
            return 1.30
        if set(s) == {"="}:
            return 2.20
        return 2.00 if s in {"+", "-", "–", "—", "/"} else 1.65
    if s[-1] in SEPARATORS:
        return SEPARATORS[s[-1]]
    if s.isdigit():
        return 1.19
    if (s.isalpha() and s.islower() and len(s) <= 3
            and not previous.startswith(" ")):
