programs.sol:
"""Approximate a horizontal-whitespace detector using only token shapes.

Tabs joined to text have the strongest response; consecutive tabs are weaker.
Space-only tokens respond directly after a newline, with strength depending
on run length. Runs of nonbreaking spaces also receive a positive response.
Some tab and indentation responses are boosted early in a document.
Text without tabs and plain newlines receive zero; within-line spaces
receive nearly zero.
State (previous token and position) resets at document boundaries.
"""

from math import sqrt

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    next_carry = (document, token, position + 1)
    newline = previous.endswith('\n')
    repeated_tab = '\t' in previous and not newline
    early = 1.0 / sqrt(1.0 + position / 8.0)
    value = 0.0
    if '\t' in token:
        word = token.strip(' \t\r\n')
        if word:
            value = 3.4 if repeated_tab else 5.3
            value += 1.18 * early - 0.27
        elif '\n' in token or '\r' in token:
            if ' ' in token:
                value = 0.75
            elif token.count('\t') > 1:
                value = 1.0
            else:
                value = 2.05 if previous[-1:].isdigit() else 1.65
        elif set(token) == {'\t'}:
            if len(token) == 1:
                if repeated_tab:
                    value = 1.7 if previous.count('\t') == 1 else 1.15
                else:
                    value = 3.1 if newline else 2.55
                value += 1.32 * early - 0.32
                if position == 0:
                    value = 1.44
            else:
                value = 2.0 if newline else 1.35
                value += 0.51 * early - 0.12
        else:
            spaces = token.count(' ')
            if spaces <= 2:
                value = 2.2
            elif spaces % 4 == 0:
                value = 1.5
            else:
                value = 1.97
    elif token and not token.strip(' '):
        if position == 0:
            value = 0.08
        elif newline:
            length = len(token)
            if length == 1:
                value = 0.69
            elif length == 2:
                value = 0.47
            elif length == 3:
                value = 0.58
            else:
                value = 0.74 if length % 2 else 0.56
            value += 0.28 * early - 0.07
        else:
            value = -0.05 if len(token) > 1 else -0.01
    elif token and not token.strip('\u00a0') and len(token) > 1:
        value = 0.6
    return next_carry, value

