        at_line_start = True
    else:
        at_line_start = carry[1]

    if token.startswith("\t") and token[1:].strip():
        value = 4.5
    elif token and token.isspace() and "\t" in token:
        value = 2.7 if at_line_start else 2.3
    elif token and token.isspace() and set(token) == {" "} and len(token) >= 2:
        value = 0.58 if at_line_start else -0.06
    elif token == " " and at_line_start:
        value = 0.08
    else:
        value = 0.0

