READS = ()

PREDICATE_VERBS = {
    "show", "vary", "simulate", "expanding", "demonstrated",
    "illuminating", "modifying", "combines", "develop", "assume",
    "demonstrates", "determine", "selecting", "relate", "engage",
    "evaluating", "represent", "allowing", "describe", "include",
    "compute", "tolerate", "suggests", "suppose", "illustrating",
    "cooperate", "satisfies", "provide", "occurs", "includes", "apply",
    "provides", "consist", "finds", "realizes", "contributes", "derive",
    "promoting",
}


def is_observed_verb(word):
    word = word.lower()
    if word in PREDICATE_VERBS:
        return True
    return len(word) >= 5 and any(
        form.startswith(word) for form in PREDICATE_VERBS
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = "" if carry is None or carry[0] != doc else carry[1]
    hit = False
