programs.sol:
"""Approximate a detector for the spelling family of 'point'.

Singular point is strongest, plural points and pointing weaker. Common
technical phrases attenuate it, while 'the point' strengthens it. The
response partly persists into 'of' and some suffixes. Several other
languages' point spellings and geometric synonyms get smaller responses.
Only a short text tail and the preceding response are carried between tokens.
"""
import re

READS = ()
FORMS = {
    'point': 3.85, 'points': 3.1,
    'pointing': 1.8, 'pointed': 1.56,
    'pointer': 0.56, 'pointers': 0.43, 'pointless': 1.12,
}
VERY_WEAK = {'floating', 'decimal', 'entry', 'fixed', 'mid'}
WEAK = {'starting', 'intersection', 'focal', 'check', 'break', 'power', 'touch'}
MODERATE = {'critical', 'highest', 'lowest', 'contact', 'reference', 'nodal'}
TRANSITION = {'melting', 'boiling', 'turning'}
OTHER_POINT_SPELLINGS = {
    'punto', 'ponto', 'punkt', 'punk', 'điểm', '점',
    'نقط', 'نقطة', 'نقاط', 'נקודה', 'נקודת',
}


def response(token, previous):
    word = token.strip()
    root = word.lower().lstrip('_.(-')
    if root in FORMS:
        value = FORMS[root]
        if root in {'point', 'points'}:
            plural = root == 'points'
            if word.lstrip('_.(-')[:1].isupper():
                value = 3.25 if plural else 4.3
            elif word.startswith(('(', '_')):
                value -= 0.9
            elif not token[:1].isspace():
                value -= 0.3
            if previous in VERY_WEAK:
                value = 1.5 if plural else 1.7
            elif previous in WEAK:
                value = 1.8 if plural else 2.4
            elif previous in MODERATE:
                value = 2.45 if plural else 2.9
            elif previous in TRANSITION:
                value = 2.6 if plural else 3.2
            elif previous == 'the':
                value += 0.45 if plural else 0.9
            elif previous in {'key', 'only', 'new'}:
                value += 0.6
            elif previous == 'a':
                value += 0.2
            elif previous in {'that', 'some'}:
                value -= 0.3
            return value, 0.38 if plural else 0.49
        return value, 0.2
    if root.endswith(('point', 'points')):
        value = 0.5 if root.endswith('points') else 0.85
        if root.startswith(('mid', 'view', 'stand', 'break')):
            value = 1.1
        elif root.startswith(('power', 'pin')):
            value = 0.27
        elif root.startswith(('qpoint', 'startpoint')):
            value = 1.85
        return value, 0.55
    if word == 'ポイント':
        return 2.6, 0.0
    if root in OTHER_POINT_SPELLINGS:
        return 1.4, 0.0
    if root in {'puntos', 'pontos', 'punkte', 'точ', 'точка', 'точки'}:
        return (1.7 if root == 'точки' else 1.0), 0.0
    if word in {'点', '點'}:
        return 0.85, 0.0
    if word.endswith(('点', '點')):
        if word in {'节点', '站点', '地点', '网点'}:
            return 0.2, 0.0
        numbered = word.startswith(('一', '二', '三', '两', '几', '这', '這'))
        return (1.6 if numbered else 1.0), 0.0
    if root in {'purpose', 'purposes', 'dot', 'dots', 'vertex', 'vertices'}:
        return 0.35, 0.5
    return 0.003, 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, strength, persistence = '', 0.0, 0.0
    else:
        _, tail, strength, persistence = carry
    match = re.search(r'([^\W\d_]+)[_-]?$', tail.rstrip())
    previous = match.group(1).lower() if match else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value, next_persistence = response(token, previous)
    if word.lstrip('_-') == 'of':
        value += strength * (persistence if token.startswith(' ') else 0.28)
    elif word in {'in', 'on'}:
        value += 0.07 * strength
    elif word in {'to', 'at', 'where'}:
        value += 0.02 * strength
    elif token.isspace():
        value += 0.05 * strength
    elif token in {'ing', 'ed', 'er', 'ers', 'e'} and persistence:
        value += (0.23 if token == 'ing' else 0.13) * strength
    return (document, (tail + token)[-60:], value, next_persistence), float(value)

