programs.sol:
"""Approximate inclusive planning and guided-exposition wording.

Training examples repeatedly activate on "let's", "we will", and
"we'll". Those cues get strong positives; "I" and "you" get smaller
future responses. The rules also cover "going to", verbs for examining
or recalling a topic, instructional text names, "we will now", and
"our purposes". "We all" and specified "let/lets" objects are negative.
Unrecognized wording is zero. This is a local wording approximation,
not a complete semantic detector of future tense or invitations.
"""
import re

READS = ()
# Plain future and contracted future values, by grammatical subject.
FUTURE = {
    "we": (2.4, 3.1), "i": (0.95, 1.5), "you": (0.76, 1.3),
    "he": (0.18, 0.5), "she": (0.18, 0.5), "they": (0.20, 0.5),
    "it": (0.05, 0.22), "this": (0.27, 0.25),
}
STRONG_GUIDING = {"see", "discuss", "learn", "explore", "dive", "delve"}
MEDIUM_GUIDING = {"look", "focus", "begin", "examine", "talk", "cover"}
TEXT_PARTS = {"post", "posts", "article", "blog", "section", "chapter",
              "lesson", "guide", "tutorial"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    word = token.strip().lower().replace("’", "'")
    words = re.findall(r"[a-z]+|'[a-z]+", tail.lower().replace("’", "'"))
    recent = (['', '', ''] + words)[-3:]
    older, before, prev = recent
    value = 0.0
    if word == "'s" and prev == "let":
        value = 1.60
    elif word in {"will", "shall", "'ll"}:
        subject = before if prev in {"now", "then", "also"} else prev
        value = FUTURE.get(subject, (0.07, 0.25))[word == "'ll"]
        if word == "shall":
            value *= 0.75
    elif word in {"'re", "'ve", "'m"}:
        if word == "'re":
            value = 0.76 if prev == "we" else 0.23 if prev == "you" else 0.04
        elif word == "'ve":
            value = 0.55 if prev == "we" else 0.19
        else:
            value = 0.19
    elif word in {"going", "gonna"}:
        value = 0.22
        if prev in {"'m", "am"}:
            value = 0.80
        elif prev in {"'re", "are"}:
            value = 1.35 if before == "we" else 0.55
    elif word == "to" and prev == "going":
        value = 1.0
        if before in {"'m", "am"}:
            value = 1.55
        elif before in {"'re", "are"}:
            value = 2.10 if older == "we" else 1.45
    elif word in STRONG_GUIDING | MEDIUM_GUIDING:
        strength = 1.0 if word in STRONG_GUIDING else 0.55
        value = {"see": 0.08, "explore": 0.30, "focus": 0.22,
                 "learn": 0.10, "dive": 0.60, "delve": 1.0}.get(word, 0.0)
        boost = 0.0
        if prev == "we":
            boost = 0.8
        elif prev in {"will", "shall", "'ll"}:
            boost = 2.0 if before == "we" else 0.85
        elif prev == "'s" and before == "let":
            boost = 1.0
        elif prev in {"me", "us"} and before == "let":
            boost = 0.65
        value += strength * boost
    elif word in {"now", "be"} and prev in {"will", "shall", "'ll"}:
        value = (1.4 if word == "now" else 0.8) if before == "we" else 0.25
    elif word in {"saw", "seen", "discussed", "explored"}:
        value = 0.20
        if prev == "we" or (before == "we" and prev in {"have", "'ve"}):
            value = 1.50 if word == "saw" else 1.0
    elif word == "purposes":
        value = 1.30 if prev == "our" else 0.20
    elif word in TEXT_PARTS:
        value = 0.30 if word in {"post", "posts", "article", "blog",
                               "lesson", "tutorial"} else 0.15
        if prev == "this":
            value += 0.35
        if word == "guide" and prev in {"will", "'ll"}:
            value = 1.30
        if word in {"post", "posts"} and prev == "blog":
            value = 1.10
    elif word == "all" and prev == "we":
        value = -0.65
    elif word == "lets":
        value = 0.53
    elif prev in {"let", "lets"}:
        value = {"you": -1.50, "it": -1.05, "the": -1.0, "this": -1.0,
                 "us": -0.25, "your": -0.65, "them": -0.50}.get(word, 0.0)
    return (doc, (tail + token)[-80:]), float(value)

programs.haiku:
"""Future and intention markers after a person subject.

layers.0.mlp.down_proj:4467 fires on the word that announces something a person is
about to do, the word right before a bare verb:
  - "will" and "'ll" after a person: "we WILL", "we'LL" (strongest), "I WILL", "you WILL"
  - "'s" in "Let'S" ("Let's see", "let's do")
  - "'re" in "we'RE" and "to" in "are going TO"
  - "see" in "Let me SEE"
Its size depends on the subject: "we" is strongest, then "let", "I", "you"; "they" is
weak; "it", "that", "this", "there" are about 0. All other tokens give 0.
"""

READS = ()

# How strongly each subject word before a future marker drives the component.
SUBJECT = {"we": 2.5, "let": 1.6, "i": 1.2, "you": 1.1, "they": 0.2}
MARKERS = {"will", "'ll", "’ll", "'s", "’s"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    if len(prefix) < 2:
        return carry, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    if cur in MARKERS:
        if cur in ("'s", "’s") and prev != "let":
            return carry, 0.0  # "'s" counts only in "let's"
        return carry, SUBJECT.get(prev, 0.0)
    if cur in ("'re", "’re") and prev == "we":
        return carry, 0.6
    if cur == "to" and prev == "going":
        return carry, 1.0
    if cur == "see" and prev == "me" and len(prefix) > 2:
        if prefix.token_strings[-3].strip().lower() == "let":
            return carry, 0.6
    return carry, 0.0

