"""A lexical approximation of the 林 / forest / lin response.

Predict a large negative activation for 林, smaller ones for forest
compounds and lin-like spellings, and zero otherwise. The rules use the
current token, not a sentence's topic. A byte fragment that finishes 林
is recognized from the decoded text. Weak, diffuse responses are omitted.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.0

    # Chinese woodland vocabulary, plus 柏林 (Berlin).
    if word == '林':
        value = -5.2
    elif word == '林业':
        value = -3.5
    elif word in ('森林', '树林'):
        value = -2.2
    elif word in ('园林', '柏林'):
        value = -1.6
    elif word in ('丛林', '森林公园'):
        value = -0.8
    elif lower in ('forest', 'forests'):
        value = -1.65
    elif lower in ('forestry', 'woodland', 'woodlands'):
        value = -0.9

    # Lin/ling spellings in Chinese, Japanese, Russian, and Korean.
    elif word in ('琳', 'リン', 'лин', '림'):
        value = -1.0
    elif word in ('临', '臨', '陵', '玲'):
        value = -0.6
    elif word == '临床':
        value = -1.05
    elif lower == 'lin':
        value = -1.05 if token == ' lin' else -1.7

    # Latin lin fragments in medical words, names, and technical words.
    elif lower in ('clinical', 'clin'):
        value = -1.0
    elif lower in ('clinically', 'clinician', 'clinicians'):
        value = -0.7
    elif lower == 'berlin':
        value = -1.2
    elif lower in ('franklin', 'lind', 'linux', 'liner'):
        value = -0.8
    elif lower == 'lincoln':
        value = -0.5
    elif lower in ('linear', 'ling', 'lyn'):
        value = -0.25
    elif lower == 'lined':
        value = -0.55 if token.startswith(' ') else -0.15
    elif lower == 'lint':
        value = -0.15 if token.startswith(' ') else -0.65

    if '\ufffd' in token and prefix.text_prefixes[-1].endswith('林'):
        value = -5.2
    return None, value

programs.haiku:
"""Layer-0 MLP down-projection component 4468: a "forest / lin" token detector.

What it does: the component is silent on almost every token. It turns negative on
tokens that name a forest or spell the sound "lin":

- the Chinese character 林 (forest; also pinyin "lín" and the surname Lin): strongest,
  about -5 on its own, about -2 inside a longer Chinese word such as 森林 or 林业;
- English forest words ("forest", " Forest", "forestry"): about -1.8;
- the bare token "lin" / "lint" / "Lin": about -1.7;
- words starting "clin" (clinical, clinician, clin): about -1.0;
- other words starting "lin" (Linux, liner, Lincoln, linear), except line/link/ling
  words, which stay near 0: about -0.8.

Everything else predicts 0. The program reads only the current token, so it needs no
carry between positions.

Why: the big negative spikes come from these few tokens, so a short word list captures
most of the variance. A per-token lookup table would do better in-sample but is a
table of arbitrary ids; this rule set is the concept.
"""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    if raw == "林":
        value = -5.0
    elif "林" in raw:
        value = -2.0
    elif "forest" in word:
        value = -1.8
    elif word in ("lin", "lint"):
        value = -1.7
    elif word.startswith("clin"):
        value = -1.0
    elif word.startswith("lin") and not word.startswith(("line", "link", "ling", "lining")):
        value = -0.8
    else:
        value = 0.0
    return None, float(value)

