"""Approximate an inline-span opener signal.

Respond to opening square/curly brackets, quotes and generic type arguments.
Quotes after articles/prepositions suggest a named item and respond strongly;
quotes after sentence punctuation, or in printing/prompting calls, are weak.
Closing delimiters and block-opening braces have little response. This omits
idiosyncratic responses to particular ordinary words and code identifiers.
"""
import re

READS = ()
DETERMINERS = set('a an the this these those my your his her its our their'.split())
PREPOSITIONS = set('of in on at by for from to with without using via'.split())
TEXT_IO_CALLS = set(
    ('print printf println sprintf write writeline '
     'log info debug warn error input').split()
)
CODE_OR_RESOURCE_CALLS = set('require open client patch eval'.split())
PRIMITIVE_TYPES = set(
    'int long float double bool boolean char string str any number void'.split()
)
QUOTES = {
    ' "', " '", ' `', ' “', ' ‘', ' «', '“', '‘',
    '("', "('", '(`', '="', "='",
}


def quote_value(s, previous):
    word = previous.strip().lower()
    single, code = s == " '", '`' in s
    if s.startswith('('):
        name = re.split('[^a-z]+', word)[-1]
        if name in TEXT_IO_CALLS:
            return 0.01
        return 0.8 if name in CODE_OR_RESOURCE_CALLS else 0.37
    if s.startswith('='):
        return 0.4
    if word in DETERMINERS or word in PREPOSITIONS:
        return 0.96 if single else 0.87
    if word.endswith(('.', '!', '?', '。', '！', '？')):
        return 0.42 if code else 0.15 if single else 0.02
    if word.endswith((':', '：')):
        return 0.32 if single or code else 0.01
    if word.endswith(','):
        if single:
            return 0.59 if "'" in word else 0.4
        return 0.4 if code else 0.34 if '"' in word else 0.17
    if '\n' in previous:
        return 0.1 if s in ('“', '‘') else 0.3
    if not word:
        return 0.49 if single else 0.38
    if not any(c.isalpha() for c in previous):
        return 0.48 if single else 0.35 if code else 0.25
    return 0.77 if code else 0.74 if single else 0.65


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    same = (len(prefix.token_ids) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same else ''
    t = s.lstrip()
    value = 0.0
    # List/index openers, including brackets fused with an identifier.
    if '[' in s and ']' not in s:
        value = 0.61
        if t.startswith('['):
            tail = t[1:]
            value = 0.88 if tail.isidentifier() else 0.48
            if not tail:
                value = 0.71 if s.startswith(' ') else 0.83
                if previous.rstrip().endswith('\\'):
                    value -= 0.4
            elif tail.startswith(('"', "'")):
                value = 0.35 if s.startswith(' ') else 0.5
            elif tail.startswith('['):
                value = 0.85
            elif tail.startswith('@'):
                value = 0.07
        elif t.startswith('\\['):
            value = 0.33
        if '\n' in s:
            value = 0.23
    elif t == '][':
        value = 0.13
    # Curly math groups and inline containers, but not whole code blocks.
    elif '{' in s and '}' not in s and '\n' not in s:
        value = 0.64
        if t.endswith(('{"', "{'")):
            value = -0.08
        elif t.startswith('_{'):
            value = 0.78
        elif t.startswith('^{'):
            value = 0.66
        elif t == '{':
            value = 0.53
            if previous.strip() in ('begin', 'end', 'text'):
                value = 0.09
            elif previous.strip() == 'frac':
                value = 0.83
        elif t == '{\\':
            value = 0.32 if s.startswith(' ') else 0.64
    elif t == '}_{':
        value = 0.39
    # Quotes which leave their contents to the following token.
    elif s in QUOTES:
        value = quote_value(s, previous)
    elif t in ('【', '「', '『', '《'):
        value = 0.52
    # Generic types: <T, <string, or List followed immediately by <.
    elif t.startswith('<') and '>' not in t:
        tail = t[1:]
        generic = (tail.isidentifier()
                   and (tail[0].isupper() or tail in PRIMITIVE_TYPES))
        adjacent_type = (s == '<' and previous.strip()
                         and previous.strip()[0].isupper())
        if generic or adjacent_type:
            value = 0.66
    elif s in ('\\"', "\\'", ' "\\'):
        value = -0.15
    elif '\n' in s and '{' in s:
        value = -0.03
    return None, float(value)

programs.luna:
"""Opening punctuation weakly predicts a positive activation, with different
punctuation families getting slightly different strengths.
"""

READS = ()
QUOTES = '"\'“‘«‹「『'
BASE = 0.003
SCALE = 0.30


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()
    if not token:
        return None, BASE

    cue = 0.0
    if token[0] in QUOTES:
        cue = 0.58 if token[0] == '"' else 0.76
    elif token[0] == '[':
        cue = 0.78
    elif token[0] == '【':
        cue = 0.52
    elif token[0] == '{':
        cue = 0.50
    elif token.startswith(("_{", r"\[")):
        cue = 0.84
    elif token.startswith("<") and len(token) > 1 and token[1].isalpha():
        cue = 0.84
    elif token[0] in "=(" and any(c in QUOTES for c in token[1:3]):
        cue = 0.76

    return None, BASE + SCALE * cue

programs.sol:
"""Approximate numerical-computing and document-boundary responses.

R/MATLAB syntax, tabular objects, array operations, and spreadsheet terms
give positive responses. Recent numerical vocabulary strengthens selected
ambiguous terms. The coefficients approximate training responses. Hash/dollar
sigils depend on line position and code/math context. Document ends are negative.
Other tokens get zero. Context resets at document boundaries.
"""
import re

READS = ()
DATA_WORDS = set('data dataset datasets table tables matrix matrices '
                 'list lists vector vectors array arrays'.split())
CODE_WORDS = set('function functions command commands formula formulas '
                 'syntax package packages library libraries'.split())
ANALYSIS_NAMES = set('numpy pandas scipy ggplot ggplot2 dplyr tidyr tibble '
                'matplotlib seaborn reshape arange'.split())
PLOT_WORDS = set('plot plots plotting gg plt'.split())
ARRAY_CONSTRUCTORS = {'zeros', 'ones', 'arange', 'linspace'}
SPREADSHEETS = {'spreadsheet', 'worksheet', 'workbook', 'xlsx'}
WORDS = DATA_WORDS | CODE_WORDS | ANALYSIS_NAMES | PLOT_WORDS
WORDS |= ARRAY_CONSTRUCTORS | SPREADSHEETS
WORDS |= {'matlab', 'excel', 'dataframe', 'frame', 'pack', 'series',
          'r', 'true', 'false', 'na', 'nan', 'pd', 'df', 'sheet', 'sheets'}
NUMERICAL_CONTEXT = re.compile(
    r'(?i)\b(matlab|numpy|pandas|dataframe|ggplot2?|dplyr|rstudio|scipy|'
    r'excel|stata|spss|sas|mcmc|covariance|regression|eigenvectors?|quantile|'
    r'polyfit|spreadsheet|worksheet|workbook)\b|<-|data\.frame|'
    r'install\.packages|library\(')
CODE_CONTEXT = re.compile(r'\b(function|return|class|public|const|var|echo|'
                          r'foreach|import|def|printf|include)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent = '' if first else carry[1]
    token = prefix.token_strings[-1]
    s = token.strip()
    word = s.lstrip('.(').lower()
    carry = (doc, (recent + token)[-800:])
    if s == '<|endoftext|>':
        return carry, -1.10
    # Recognize a known software name even if the tokenizer splits it.
    completed = (recent[-12:] + token).lower()
    if s and completed.endswith('matlab'):
        return carry, 1.8
    if s and word not in ANALYSIS_NAMES and completed.endswith(
            ('pandas', 'matplotlib', 'tibble', 'dplyr')):
        return carry, 0.8
    if (word not in WORDS and s not in {'<-', '<<-', '%>%', '>%',
                                      '[,', '(:,', '%', '>', '>>', '>>>'}
            and '#' not in s and '$' not in s):
        return carry, 0.0
    numerical = min(1.0, len(NUMERICAL_CONTEXT.findall(recent)) / 2)
    code = min(1.0, len(CODE_CONTEXT.findall(recent[-250:])) / 3)
    space = float(token.startswith(' '))
    line_start = float(not recent.rsplit('\n', 1)[-1].strip())
    if s == '#':
        value = -0.34 if first else 0.99 - 0.35*space - 0.44*line_start - 0.18*code
    elif s and set(s) == {'#'}:
        value = 0.33 - 0.30*line_start + 0.23*numerical
    elif '#' in s:
        value = 0.75
        if s.startswith('#!'):
            value = 0.0
        elif s.startswith('&#') or s == '#include':
            value = 0.30
        elif '[' in s or s.startswith(('#define', '#endif', '#if', '#pragma')):
            value = 0.52
    elif '$' in s:
        math_context = min(1.0, recent.count('$') / 4)
        math_context *= 1.0 if '\\' in recent else 0.5
        value = 0.51 + 0.08*space + 0.28*code - 0.54*math_context
        if s in {'$$', '$,', '$.', ')$', '}$'}:
            value = -0.03
        elif s.endswith('$\\'):
            value = 0.12
        elif '\\$' in s:
            value = 0.75
        elif recent.endswith('\\'):
            value += 0.58
        if first:
            value = 0.0
    elif s == '%':
        value = 0.13 + 0.33*space + 0.22*numerical + 0.72*line_start
    elif s in {'>', '>>', '>>>'}:
        value = 0.07 + 0.37*space + 0.21*numerical - 0.12*code + 0.52*line_start
        if token.endswith('\n'):
            value = 0.0
    elif s in {'<-', '<<-'}:
        value = 1.0 + 0.8*numerical + 0.4*code
    elif s in {'%>%', '>%'}:
        value = 2.4
    elif s in {'[,', '(:,'}:
        value = 0.9
    elif s in {'TRUE', 'FALSE'}:
        value = 1.3 + 0.9*numerical - 0.3*code
    elif s in {'NA', 'NaN'}:
        value = 0.2 + 0.8*numerical
    elif s == '.frame':
        value = 3.7 if recent.rstrip().endswith('data') else 0.2
    elif s == '.pack':
        value = 1.9 if recent.rstrip().endswith(('install', 'remove')) else 0.1
    elif word == 'matlab':
        value = 1.65
    elif word == 'excel':
        value = 0.7 + 0.2*numerical
    elif word in ARRAY_CONSTRUCTORS:
        value = 0.8 if s.startswith('.') else 0.4
    elif word in SPREADSHEETS:
        value = 0.5
    elif word in {'sheet', 'sheets'}:
        value = 0.35 if re.search(
            r'(?i)excel|spreadsheet|worksheet|workbook|\bcell|\bcolumn', recent) else 0.0
    elif s.lstrip('(') in {'pd', 'df'}:
        value = 0.2 + 0.2*space + 0.2*numerical
    elif word in ANALYSIS_NAMES:
        value = 0.5 + 0.15*numerical
    elif word == 'dataframe' or s == '.Series':
        value = 0.8 + 0.2*numerical
    elif word in DATA_WORDS:
        value = 0.23 + 0.26*numerical - 0.06*code
    elif word in CODE_WORDS:
        value = 0.14 + 0.18*space + 0.54*numerical - 0.04*code
        if s == 'library' and line_start:
            value = 1.4 + 0.8*numerical
        if first:
            value -= 0.47
    elif word in PLOT_WORDS:
        value = 0.2 + 0.09*space + 0.3*numerical - 0.12*code + 0.16*line_start
    elif s == 'R':
        value = 0.12 + 0.5*numerical
        if re.search(r'(?i)\busing\s*`?$', recent[-25:]):
            value += 1.0
        elif recent.endswith('```'):
            value += 0.8
    else:
        value = 0.0
    return carry, float(value)

programs.haiku:
"""Layer-0 down-projection feature: an end-of-document detector plus a
programming / data-science detector.

* Strongly negative on the end-of-text token (a document boundary).
* Positive on the hash sign (comments, preprocessor, markdown headings), on
  other code-style symbols ($ % > <- ::), and on programming and data-analysis
  vocabulary (R, MATLAB, Excel, Python data libraries, plotting, tables).
* Zero everywhere else.
"""
READS = ()

END_OF_TEXT = "<|endoftext|>"
HASH = {"#", "##", "#include", "#define"}
SYMBOLS = {"$", "%", ">", "\\$", "::", "${"}
CODE_WORDS = {
    "library", "TRUE", "FALSE", "MATLAB", "Excel", "plot", "gg", "numpy", "pandas",
    "matplotlib", "DataFrame", "Series", "frame", "data", "table", "matrix", "formula",
    "function", "functions", "list", "package", "command", "numeric", "INTEGER",
    "paste", "install", "setq", "plt", "pd", "df",
}
ARROW = {"<-"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = s.strip()
    if s == END_OF_TEXT:
        value = -1.1
    elif t in HASH or t.startswith("#"):
        value = 0.45
    elif t in ARROW:
        value = 1.7
    elif t in SYMBOLS:
        value = 0.2
    elif t in CODE_WORDS:
        value = 0.35
    else:
        value = 0.0
    return None, value

programs.luna:
"""Mark document endings and a small set of code/math/markup cues."""
READS = ()
MARKERS = {'#', ' #', '$', ' $', '$(', '&#', '%', ' %'}
TECHNICAL = {
    'matrix', 'datasets', 'tables', 'output', 'matlab', 'latex',
    'proc', 'airy', 'Integer', 'R',
}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        value = -1.1
    elif token in MARKERS or token.strip() in TECHNICAL:
        value = 0.4
    else:
        value = 0.0
    return None, value

programs.sol:
"""A spelling-sensitive negative response to res- word pieces.

The bare syllable is strongest, especially beside filename punctuation.
Completed words have different strengths by word family; rest-/restrict-
are notably weak. The French/German article 'des' also elicits a response.
Adjacent fragments are joined when the previous piece is res. A few
Chinese counterparts share a weaker response. A bare syllable uses the
preceding token to tell a word start from an internal fragment. The rules
use spelling and word families, not sentence meaning.
"""

READS = ()
WORD_START = ' \t\r\n.,/\\-_:;=(<"\''

# Prefixes group inflected words and programming identifiers by familiar roots.
FAMILIES = (
    ('respectively', -4.5), ('respectable', -1.5), ('respect', -3.7),
    ('resolv', -3.0), ('resolut', -3.4), ('resumed', -1.5), ('resum', -3.1),
    ('respiratory', -3.2), ('respir', -1.3),
    ('responsib', -1.5), ('responsive', -1.6),
    ('response', -0.6), ('respond', -0.5), ('resp', -2.0),
    ('residenc', -2.9), ('residen', -2.3), ('residu', -1.9),
    ('resid', -1.8), ('resin', -2.8), ('resiz', -2.2),
    ('resist', -1.6), ('resilien', -2.2), ('reson', -2.1),
    ('resort', -2.3), ('resign', -2.0), ('resal', -2.5),
    ('resourc', -1.1), ('research', -1.0), ('result', -1.3),
    ('reset', -1.6), ('reserv', -1.2), ('rescu', -1.3),
    ('resembl', -1.0), ('restaurant', -0.6),
    ('preserv', -0.9), ('fresh', -0.9),
)


# Common Chinese equivalents of the most responsive English word families.
TRANSLATIONS = (
    (frozenset(('居民',)), -2.1),          # residents
    (frozenset(('残', '电阻', '尊重')), -2.4),  # remnants, resistance, respect
    (frozenset(('结果', '結果', '资源', '資源', '分别', '分別',
                '责任', '責任', '居', '居住')), -1.0),
)


def family_strength(word):
    for root, strength in FAMILIES:
        if word.startswith(root):
            if word in ('results', 'resulted', 'resources', 'residents'):
                strength *= 0.7 if word.startswith('result') else 0.75
            if word == 'resulting':
                strength *= 0.9
            if word == 'responsible':
                strength = -2.1
            return strength
    if word.startswith(('rest', 'ress')):
        return -0.1
    if word.startswith('res'):
        return -0.7
    if (len(word) == 4 and word.endswith('res')
            and word[0] in 'bcdfghjklmnpqrstvwxyz'):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = raw.lstrip(WORD_START).lower()
    value = 0.0
    if word == 'res':
        if raw[:1].isspace():
            value = -4.5 if raw.endswith('res') else -4.8
        elif raw.lower() != 'res':
            value = -6.5 if raw[:1] in '.,/-' else -4.0
            if raw.endswith('Res'):
                value = -4.8
        elif raw == 'Res':
            value = -5.2
        elif (previous and previous[-1].isalpha()
              and not previous.endswith(('\\n', '\\t'))):
            length = len(previous.strip())
            value = -2.3 if length == 1 else -1.8 if length == 2 else -1.2
        else:
            value = -5.0
    elif word == 'des':
        value = -1.2 if raw != 'des' else -0.7
    elif word == 'rés':
        value = -2.5 if raw[:1].isspace() else 0.0
    else:
        value = family_strength(word)
        previous_word = previous.lstrip(WORD_START).lower()
        if previous_word == 'res' and raw.isalpha():
            joined = 'res' + raw.lower()
            value = 0.65 * family_strength(joined)
            if joined == 'respiration':
                value = -0.5
            elif joined in ('resume', 'resumed', 'resumen'):
                value = -1.6 if joined != 'resumen' else -0.4
        if word.startswith('disrespect'):
            value = -3.0
        elif word.startswith('unresolv'):
            value = -1.5
        for words, strength in TRANSLATIONS:
            if word in words:
                value = strength
                break
    return (doc, raw), float(value)

programs.luna:
"""A spelling-sensitive cue: token pieces beginning “res-” get a negative vote.
The “respect-”, “resid-”, and “resol-” families get stronger votes than the
more general “res-” start; the standalone token spelling “des” is another cue. It
recognizes recurring word starts, not the words' meanings or their context."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold().strip()
    if token.startswith("respect"):
        return None, -4.0
    if token.startswith("resid"):
        return None, -2.1
    if token.startswith("resol"):
        return None, -3.2
    if token.startswith("res"):
        return None, -1.4
    if token == "des":
        return None, -1.15
    return None, 0.0

programs.sol:
"""Detect message/thought endings, spellings of 'of', and a few lexical senses.

End-of-message/thought markers are strongly positive, closing tool tags
negative.  'of' has positive responses outside its normal leading-space
lowercase form; size/type queries and equality tests share smaller signals.
Selected Chinese, Japanese, and English tokens meaning genuine/truly also
respond.  Ordinary text is mostly zero: small lexical effects are omitted.
"""
READS = ()

MARKERS = {
    '</think>': 1.07,
    '</tool_call>': -0.305,
    '</tool_response>': -0.13,
    '<tool_response>': -0.083,
    '<|endoftext|>': -0.023,
    '<think>': 0.061,
    '<tool_call>': 0.04,
}
OF_SPELLINGS = {
    'of': 0.32,
    'Of': 0.75,
    'OF': 0.49,
    ' Of': 0.50,
    ' OF': 0.27,
    '_of': 0.64,
    '_OF': 0.90,
    '-of': 0.47,
    '.of': 0.62,
    '(Of': 0.68,
}
GENUINENESS = {
    ' truly': 0.23,
    '本当に': 0.50,
    '真正': 1.36,
    '真正的': 0.79,
}


def step(carry, prefix, upstream):
    token, document = prefix.token_strings[-1], prefix.document_ids[-1]
    age, previous = (0, '') if carry is None or carry[0] != document else (
        carry[1] + 1, carry[2])
    value = MARKERS.get(token, OF_SPELLINGS.get(token, GENUINENESS.get(token, 0.0)))
    word = token.lstrip(' *(,.')
    if token == '<|im_end|>':
        value = 1.13 if age <= 10 else 1.22 if age <= 100 else 1.26
    elif token == '<|im_start|>':
        value = 0.10 if age == 0 else 0.007
    elif token == ' of':
        if age == 0:
            value = 0.206
        elif previous.strip().isdecimal():
            value = 0.07
        elif previous == '%':
            value = -0.07
        elif not any(c.isalpha() for c in previous):
            value = 0.13
    elif word == 'sizeof':
        value = 0.49
    elif word in {'typeof', 'instanceof'}:
        value = 0.26
    elif word in {'indexOf', 'IndexOf', 'valueOf'}:
        value = 0.40
    elif word == 'TypeOf':
        value = 0.72
    elif word == 'toBe':
        value = 0.72
    elif word == 'isEqualTo':
        value = 0.58
    elif word in {'toEqual', 'EqualTo', 'toBeTruthy', 'toBeFalsy'}:
        value = 0.29
    return (document, age, token), value

programs.luna:
"""A few sparse token cues.

The main cue marks the end of a chat message, with a smaller one at the end
of a reasoning block. A weaker response tracks “of”: it is clearest in
unspaced or title-case spellings, and also appears in a few familiar words
and camel-case code names ending in Of.
"""

import re

READS = ()

_OF = re.compile(r"(?i)(?<![a-z])of(?![a-z])")
_SPACE_PREFIX_EXCEPTIONS = {
    "Of", "OF", "thereof", "sizeof", "typeof", "instanceof"
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<|im_end|>":
        return None, 1.24
    if token == "</think>":
        return None, 1.07
    if token == "</tool_call>":
        return None, -0.30
    if token == "</tool_response>":
        return None, -0.12

    stripped = token.strip()
    camel_case_of = (
        stripped.endswith("Of")
        and len(stripped) > 2
        and stripped[-3].islower()
    )
    # The frequent, space-prefixed lowercase “ of” form is near zero.
    if (
        token[:1].isspace()
        and stripped not in _SPACE_PREFIX_EXCEPTIONS
        and not camel_case_of
    ):
        return None, 0.0
    if stripped == "Of":
        return None, 0.65
    if stripped == "OF":
        return None, 0.28 if token[:1].isspace() else 0.50
    if stripped.lower() == "thereof":
        return None, 0.26
    if stripped.lower() == "sizeof":
        return None, 0.50
    if stripped.lower() == "typeof":
        return None, 0.24
    if stripped.lower() == "instanceof":
        return None, 0.24
    if stripped.endswith("_OF") and stripped.isupper():
        return None, 0.90
    if camel_case_of:
        return None, 0.43

    match = _OF.search(token)
    if not match:
        return None, 0.0
    if stripped.lower() == "of":
        return None, 0.33
    if token[0].isalpha():
        return None, 0.33
    return None, 0.48

programs.sol:
"""Local second-person address, particularly conditional clauses and questions.

'You' and 'your' receive positive signals. 'If you' and auxiliary-before-
subject questions are stronger; punctuation and clause-linking words are
weaker. A one-token trace continues onto contractions and selected predicates,
or two tokens when an intervening contraction occurs. Listed second-person
pronouns in other languages, indefinite/demonstrative words, and interest or
familiarity words have
smaller responses. Unhandled tokens receive zero. These are approximate rules,
not an account of the component's numerous small background fluctuations.
"""
import re

READS = ()
AUXILIARIES = set(
    'is are was were do does did can could will would should '
    'have has had may might must'.split()
)
CLAUSE_LINKS = set('and but because which'.split())
TIME_LINKS = set('when once until where since as then'.split())
HYPOTHESES = set('assuming suppose supposing hopefully maybe perhaps'.split())
RECIPIENT_VERBS = set('give tell show provide see'.split())
CONTRACTIONS = {"'re", '’re', "'ve", '’ve', "'d", '’d', "'ll", '’ll'}
OTHER_YOU = {'vous', 'вас', 'вам', 'あなた'}
POLITE_OR_POSSESSIVE = {'您', 'вы', 'Вы', '你的', '您的', 'votre', 'usted'}


def word(token):
    text = token.strip().strip('"“”‘()[]{}')
    if not text.startswith(("'", '’')):
        match = re.search(r'[A-Za-z]+$', text)
        if match:
            return match.group()
    return text


def address(current, previous, raw_previous):
    possessive = current.lower() != 'you'
    p = previous.lower()
    capital = previous[:1].isupper()
    value = 0.8 if possessive else 1.2
    if current[:1].isupper():
        value = 0.3 if possessive else 0.45
    if p == 'if':
        value = (2.3 if possessive else 3.2) + 0.65 * capital
        if not raw_previous.startswith(' '):
            value += 0.25
    elif p in HYPOTHESES or p == 'hope':
        value = 2.1 if possessive else 2.8
    elif p in {'whether', 'unless'}:
        value = 1.8 if possessive else 2.2
    elif p in AUXILIARIES:
        value = (1.5 if possessive else 2.5) + 1.4 * capital
        if p in {'do', 'does', 'did', 'are', 'is'}:
            value += 0.3
        if p == 'are' and raw_previous == previous:
            value += 1.0
        if p == 'will':
            value -= 1.0
        if p == 'is' and not possessive and not capital:
            value = 1.2
    elif ',' in previous or p in CLAUSE_LINKS:
        value = 0.0 if ',' in previous or p == 'but' else 0.25
    elif p in TIME_LINKS:
        value = 0.5
    elif p in {'before', 'after', 'while', 'now', 'first', 'time', 'way'}:
        value = 0.1
    elif p in {'that', 'so', 'thank', 'how', 'than'}:
        value = 0.65
    elif p == 'for':
        value = 0.95 if possessive else 1.85
    elif p in RECIPIENT_VERBS:
        value = 1.4 if possessive else 1.75
    elif previous and not any(c.isalpha() for c in previous):
        value = -0.2 if possessive and '.' in previous else 0.35
    if current[:1].isupper() and any(c.isalpha() for c in previous):
        value *= 0.7
    return value


def continuation(current, strength, default):
    if current in {"'re", '’re'}:
        return 0.72 * strength
    if current in {"'ve", '’ve'}:
        return max(-0.1, 0.65 * strength - 0.2)
    if current in {"'d", '’d'}:
        return 0.45 * strength - 0.4
    if current in {'are', 'have'}:
        return 0.44 * strength - 0.1
    if current in {'were', 'had', 'need'}:
        return 0.32 * strength - 0.08
    if current in {'want', 'know'}:
        return 0.6 * strength - 0.05
    if current in {'may', 'might'}:
        return 0.75 + 0.12 * strength
    if current in {'think', 'like', 'mean', 'wish', 'look'}:
        return 0.3 * strength
    if current in {'sure', 'looking'}:
        return 0.4 * strength
    return default


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    current, prev = word(token), word(previous)
    lower, p = current.lower(), prev.lower()
    value = 0.0
    if lower in {'you', 'your'}:
        value = address(current, prev, previous) if previous else 0.4
    elif lower in {'yours', 'yourself', 'yourselves'}:
        value = 0.75
    elif lower in OTHER_YOU:
        value = 0.55 if current[:1].isupper() else 1.1
    elif lower == 'você' or current in {'你们', '你們'}:
        value = 1.6
    elif current == '你':
        value = 1.3
    elif current in POLITE_OR_POSSESSIVE:
        value = 0.4
    elif current in {'如果你', '如果您'}:
        value = 2.25 if current == '如果你' else 1.3
    elif lower in {'anyone', 'someone', 'those'}:
        value = 0.7 if lower == 'anyone' else 0.45
        if p in AUXILIARIES:
            value += 0.6
    elif lower == 'any':
        value = 1.25 if p in {'are', 'were', 'have', 'has', 'had'} else 0.15
    elif lower in {'interested', 'familiar'}:
        value = 0.7
    if p == 'you' or (prev in CONTRACTIONS and strength != 0.0):
        value = continuation(lower, strength, value)
    new_strength = value if lower == 'you' else 0.0
    if p == 'you' and current in CONTRACTIONS:
        new_strength = strength
    return (doc, token, new_strength), float(value)

programs.haiku:
"""Second-person address detector ("you" / "your"), strongest in "if you ..." conditions.

Layer-0 MLP unit that fires on the word "you" (and "your", "yourself", and the
equivalent words in other languages: 你, 您, vous, вы, você, あなた, bạn).

How strongly it fires depends on the word just before "you":
  * after a conditional, auxiliary or modal word ("if you", "can you", "do you",
    "are you", "did you", "will you") it is strong, about 3.5;
  * after a verb or preposition ("tell you", "for you", "to you", "give you") it is
    moderate, about 1.5;
  * after punctuation or a clause-linking word (", you", ". you", "but you", "when
    you") it is weak, about 0.3;
  * after anything else it is about 1.0.
"your" fires at 0.8 times that.

Two smaller effects: a contraction ("you're", "you've") right after "you" fires at
about 1, and so does the word straight after "if you" / "do you" / "can you" when it
is not punctuation ("if you [are]", "if you [have]", "do you [want]"). Generic
addressee words "anyone" (0.8), "those" (0.45) and "someone" (0.3) get a small fixed
value. Everything else is 0.
"""
READS = ()

YOU = {"you", "yourself", "yours", "你", "您", "vous", "вы", "вас", "вам", "você",
       "你們", "你们", "あなた", "bạn"}
YOUR = {"your", "你的", "ваш"}
CONTRACTIONS = {"'re", "’re", "'ve", "’ve"}
GENERIC = {"anyone": 0.8, "those": 0.45, "someone": 0.3}
CONDITIONAL_OR_AUX = {"if", "can", "could", "do", "does", "did", "are", "have", "would",
                      "should", "will", "whether", "unless", "'t", "’t"}
VERB_OR_PREPOSITION = {"for", "to", "with", "give", "gives", "tell", "show", "help", "hope",
                       "see", "let", "like", "what", "why", "how", "of", "from", "by",
                       "than", "until", "ask", "provide", "assist", "love", "want", "get",
                       "think", "make"}
CLAUSE_LINK_OR_PUNCT = {",", ".", "!", "?", ";", ":", "\n", "and", "but", "when", "as",
                        "then", "because", "while", "before", "after", "now", "-", ")"}
PUNCT = {",", ".", "!", "?", ";", ":", "\n", '"', "”", "“"}


def gain(prev):
    """How strongly a 'you' fires, given the word before it."""
    if prev in CONDITIONAL_OR_AUX:
        return 3.5
    if prev in VERB_OR_PREPOSITION:
        return 1.5
    if prev in CLAUSE_LINK_OR_PUNCT:
        return 0.3
    return 1.0


def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings]
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    if tok in YOU:
        return None, gain(prev)
    if tok in YOUR:
        return None, 0.8 * gain(prev)
    if tok in CONTRACTIONS and prev in YOU:
        return None, 1.0
    if tok in GENERIC:
        return None, GENERIC[tok]
    if prev in YOU and prev2 in CONDITIONAL_OR_AUX and tok not in PUNCT:
        return None, 1.0
    return None, 0.0

programs.sol:
"""Local English phrase cues, especially the complement 'to'.

'Being subject to' is strongly positive; reference and intended meaning
are negative. Smaller cues distinguish intention, recipients, likelihood,
and progress. 'Mean' is usually negative, especially in clarification
questions; statistical modifiers suppress that response.
Colons after selected field labels are positive, unlike colons introducing
speech or notes. Unrecognized text gets a near-zero baseline. Only recent text
is retained, and document boundaries reset it.
"""
import re

READS = ()

# Inflections of the same reference construction have different strengths.
REFERENCE = {
    'refer': -0.96, 'refers': -1.08, 'referring': -1.00,
    'referred': -0.81, 'reference': -0.69, 'references': -0.60,
}

# Common infinitive constructions; the strongest cues are handled below.
TENDENCY = {'likely', 'tend', 'tends'}
PROGRESS = {'going', 'leading', 'leads', 'continue', 'continues', 'start'}
INTENTION = {'supposed', 'intended', 'aim', 'aims'}
DESIRE = {'want', 'wanted', 'like', 'wish'}
ATTEMPT = {'try', 'tried', 'trying', 'tries'}
RECIPIENTS = {'me', 'us', 'him', 'her', 'them', 'it'}
CONNECTIVES = {'according', 'order', 'prior'}

PRONOUN_MEAN = {'you': -0.80, 'we': -0.53, 'i': -0.40,
                'it': -0.45, 'they': -0.49, 'this': -0.43}
STATISTICAL_MEANS = {'arithmetic', 'geometric', 'harmonic',
                     'sample', 'population'}
FIELD_LABELS = {'type', 'category', 'input', 'author', 'topic', 'label'}
SPEECH = {'said', 'says', 'say', 'wrote', 'saying'}
NOTES = {'note', 'notes', 'warning', 'notice', 'disclaimer'}


def to_completion(word):
    if word == 'subject':
        return 1.39
    if word == 'subjected':
        return 0.71
    if word in REFERENCE:
        return REFERENCE[word]
    if word in {'pointed', 'pointing', 'pointer'}:
        return -0.62
    if word == 'you':
        return -0.23
    if word == 'meant':
        return -0.56
    if word in {'aimed', 'aiming'}:
        return -0.50
    for words, value in (
        (INTENTION, -0.33), (DESIRE | ATTEMPT | RECIPIENTS, -0.15),
        (TENDENCY, 0.34), (PROGRESS, 0.20),
        ({'addition'}, 0.30), (CONNECTIVES, 0.15),
    ):
        if word in words:
            return value
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = -0.001
    if token in {' to', ' TO', ' mean', ' means', ':'}:
        match = re.search(r'([A-Za-z]+)\s*$', text)
        raw_word = match.group(1) if match else ''
        word = raw_word.lower()
        if token in {' to', ' TO'}:
            value = to_completion(word)
            # A split reference word provides a weaker immediate cue.
            previous = (prefix.token_strings[-2]
                        if len(prefix.token_ids) > 1 else '')
            if word in REFERENCE and previous.strip().lower() != word:
                value *= 0.5
            if token == ' TO':
                value *= 0.6
        elif token == ' mean':
            value = PRONOUN_MEAN.get(word, -0.23)
            if word == 'would':
                value = -0.12
            elif word in STATISTICAL_MEANS:
                value = 0.0
            elif word in PRONOUN_MEAN and match:
                earlier = re.findall(r'[A-Za-z]+', text[:match.start()])
                if earlier and earlier[-1].lower() in {'what', 'did'}:
                    value -= 0.18
        elif token == ' means':
            value = -0.04
            if word == 'by':
                value = -0.25
            elif raw_word in {'it', 'this', 'no', 'a'}:
                value = -0.18
        elif raw_word == 'Subject':
            value = 0.63
        elif word == 'subject':
            value = 0.25
        elif word in FIELD_LABELS:
            value = 0.22
        elif word in SPEECH:
            value = -0.26
        elif word in NOTES:
            value = -0.16
    return (doc, (text + token)[-64:]), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:4475 (layer-0 MLP output).

It fires on the word "to" and reads which word comes just before it:
- "subject to" / "subjected to" / "likely to" -> positive (about +1.4, +0.7, +0.35);
- "refer to" / "refers to" / "referred to" / "referring to" / "reference to" / "aimed to"
  -> negative (about -0.9 to -1.1);
- "you/we/I mean" (the word " mean") -> mildly negative (about -0.24).
Everything else is predicted as 0.
"""

READS = ()

SUBJECT_TO = {"subject": 1.4, "subjected": 0.7, "likely": 0.35}
REFER_TO = {"refer": -0.97, "refers": -1.09, "referred": -0.82, "referring": -0.98,
            "reference": -0.70, "aimed": -0.52}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if prefix.position == 0:
        return None, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    if cur == " to":
        if prev in SUBJECT_TO:
            return None, SUBJECT_TO[prev]
        if prev in REFER_TO:
            return None, REFER_TO[prev]
        return None, 0.0
    if cur == " mean":
        return None, -0.24
    return None, 0.0

programs.luna:
"""Predict sparse signed responses to a few English phrase cues.

Predict positive values for "subject to" / "subjected to" and "Subject:",
negative values for reference verbs followed by "to", and a negative value
for "mean" after a pronoun. Predict zero elsewhere, omitting the many weak
context-dependent activations.
"""

import re

READS = ()

REFERENCE_WORDS = {
    "refer", "refers", "referred", "referring", "reference", "references",
    "pointed",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ""
    else:
        history = carry[1]

    previous = re.search(r"([a-z]+)$", history.rstrip().lower())
    word_before = previous.group(1) if previous else ""
    word = token.strip().lower()

    value = 0.0
    if word == "to":
        if word_before == "subject":
            value = 1.25
        elif word_before == "subjected":
            value = 0.75
        elif word_before in REFERENCE_WORDS:
            value = -0.9
    elif word == "mean" and word_before in {
        "i", "you", "we", "they", "he", "she", "it",
    }:
        value = -0.65
    elif word == ":" and word_before == "subject":
        value = 0.65

    return (doc, (history + token)[-64:]), value

