"""A local lexical detector for 'system', not for whole technical topics.

It predicts a strong negative activation on the word, plural, identifier forms,
and several translations. C# 'using System' is especially strong; common named
kinds of system attenuate it. There is a small echo in 'system of', and weaker
responses to related software, industrial and institutional vocabulary.
The only state is the previous token, reset at document boundaries.
"""
READS = ()
SYSTEM_WORDS = {'system', 'systems', 'ystem', 'ystems'}
TRANSLATIONS = {
    'sistema', 'sistemas', 'sistem', 'système', 'systèmes',
    'система', 'системы', 'истем', 'نظام', 'ระบบ',
}
# Different written forms of the same English word have different strengths.
SYSTEM_FORMS = {
    'system': -6.6, 'System': -6.1, ' SYSTEM': -5.4,
    '_SYSTEM': -6.4, '/system': -6.5, '.System': -7.35,
}
MODIFIER_GROUPS = (
    ({'operating', 'coordinate', 'solar'}, -3.05),
    ({'linear'}, -3.75),
    ({'metric', 'file'}, -4.1),
    ({'immune', 'number', 'information', 'optical', 'support'}, -4.45),
    ({'control', 'nervous', 'digestive', 'binary', 'reference'}, -4.8),
)


def response(token, previous):
    word = token.strip().lstrip('._/\\(-:').lower()
    before = previous.strip().lower()
    previous_word = before.lstrip('._/\\(-:')
    if previous_word in SYSTEM_WORDS:
        if token == ' of':
            return -1.1
        if token in {'s', 'S', 'atic'}:
            return -1.2 if token == 'atic' else -3.0
    if word in SYSTEM_WORDS:
        if previous == '<|im_start|>':
            return -4.46  # The chat role label 'system'.
        if token == ' System' and before == 'using':
            return -9.35
        if token in {'system', '_SYSTEM', '/system'}:
            return SYSTEM_FORMS[token]
        if word in {'ystem', 'ystems'}:
            return -5.5 if word == 'ystem' else -4.7
        for modifiers, value in MODIFIER_GROUPS:
            if before in modifiers:
                return value
        if token.startswith(':'):
            return -3.65
        if token.startswith('('):
            return -4.8
        if token.startswith('\t') or token.strip() == 'Systems':
            return -5.1
        return SYSTEM_FORMS.get(token, -6.1 if before in
                                {'the', 'of', 'and', 'or'} else -5.8)
    if word in {'sys', 'syst', 'sist'}:
        return -3.0 if before == 'import' else -2.0
    if word in TRANSLATIONS:
        return -3.1
    if word == 'систем':
        return -5.2
    if word in {'systematic', 'systemic', 'systematically'}:
        return {'systematic': -2.25, 'systemic': -3.4,
                'systematically': -1.2}[word]
    if word in {'filesystem', 'filesystems', 'subsystem', 'subsystems'}:
        return -3.7 if word.startswith('sub') else -2.7
    if word in {'ecosystem', 'ecosystems'}:
        return -1.3
    if token in {'系统', '系統'}:
        return -5.9
    if token == '系统的':
        return -5.2
    if token.endswith(('系统', '系統')):
        return -4.0 if token == '管理系统' else -2.7
    if token == 'システム':
        return -4.0
    if token in {'体系', '制度', '体制', '統', 'ระบ'}:
        return -2.3
    if token in {'系', '制', '製'}:
        return -0.9
    if token in {' java', ' javax'}:
        return -1.35 if before == 'import' else -0.45
    if token in {' Windows', 'Windows', ' android', '.springframework'}:
        return -1.2
    if token == ' Symfony':
        return -1.9 if before == 'use' else -1.3
    if word in {'industry', 'industries', 'industrial', 'institution',
                'institutions', 'institutional'}:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

