INSTITUTION_WORDS = {
    "industry", "industries", "institution", "institutions",
    "institutional", "university", "实业",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if "system" in word:
        return None, -5.7
    if any(term in word for term in SYSTEM_WORDS):
        return None, -2.5
    if word in SOFTWARE_NAMES:
        return None, -1.35
    if word in INSTITUTION_WORDS:
        return None, -1.0
    return None, 0.0
